window.PORTAL_DATA = {"courses": [{"id": "se4ds", "code": "M-058", "name": "Data Science For Software Engineering", "shortName": "Data Science for SE", "description": "Menyatukan prinsip rekayasa perangkat lunak dengan metode data science dan machine learning.", "status": "active", "sessions": 15, "accent": "fern"}, {"id": "ade", "code": "M-059", "name": "Advance Data Engineering", "shortName": "Advanced Data Engineering", "description": "Siklus data, arsitektur modern, ETL/ELT pipeline, storage NoSQL, data lakehouse, dan distributed processing.", "status": "active", "sessions": 13, "accent": "moss"}, {"id": "sqse", "code": "M-060", "name": "Software Quality Quality Effort", "shortName": "Software Quality & Effort", "description": "Materi akan segera ditambahkan.", "status": "soon", "sessions": 0, "accent": "sage"}, {"id": "rmse", "code": "M-061", "name": "Research Methodology For Data Science & Software Engineering", "shortName": "Research Methodology", "description": "Materi akan segera ditambahkan.", "status": "soon", "sessions": 0, "accent": "olive"}], "sessions": {"se4ds": [{"id": "pertemuan-01", "number": 1, "title": "Introduction to Data-Driven Software Development", "status": "available", "summary": "Mengapa software modern perlu memanfaatkan data, automation, dan feedback."}, {"id": "pertemuan-02", "number": 2, "title": "Fundamentals of Software Development", "status": "available", "summary": "SDLC, OOP, validasi model, dan jembatan dari model machine learning ke aplikasi."}, {"id": "pertemuan-03", "number": 3, "title": "Agile Principles", "status": "available", "summary": "Manifesto Agile, Scrum, Kanban, XP, backlog, dan sprint planning."}, {"id": "pertemuan-04", "number": 4, "title": "Agile Development Techniques", "status": "available", "summary": "User story, task board, TDD, continuous integration, dan delivery."}, {"id": "pertemuan-05", "number": 5, "title": "DevOps Principles", "status": "available", "summary": "Budaya kolaborasi, automation, monitoring, CI, dan CD."}, {"id": "pertemuan-06", "number": 6, "title": "DevOps Tools and Practices", "status": "available", "summary": "Version control, Jenkins, Docker, Kubernetes, logging, dan keamanan."}, {"id": "pertemuan-07", "number": 7, "title": "Introduction to Machine Learning", "status": "available", "summary": "Jenis ML, preprocessing, training, evaluasi, dan bias-variance."}, {"id": "pertemuan-08", "number": 8, "title": "Midterm Review", "status": "planned", "summary": "Review konsep dan latihan terpadu."}, {"id": "pertemuan-09", "number": 9, "title": "Integrating ML in Software Development", "status": "available", "summary": "ML di aplikasi, data pipeline, feature engineering, dan production."}, {"id": "pertemuan-10", "number": 10, "title": "Introduction to Data Science", "status": "available", "summary": "Data sebagai aset, proses analisis, kualitas data, dan keputusan berbasis data."}, {"id": "pertemuan-11", "number": 11, "title": "Data Science Tools and Techniques", "status": "available", "summary": "Python, R, Jupyter, analisis data, dan visualisasi."}, {"id": "pertemuan-12", "number": 12, "title": "MLOps", "status": "available", "summary": "Mengoperasikan model ML: deploy, monitor, evaluasi, dan optimasi."}, {"id": "pertemuan-13", "number": 13, "title": "Data Security and Regulation in MLOps", "status": "available", "summary": "Pipeline aman, privasi, regulasi, dan pemeliharaan model."}, {"id": "pertemuan-14", "number": 14, "title": "Integrative Project", "status": "available", "summary": "Menyatukan pengetahuan melalui proyek lintas disiplin."}, {"id": "pertemuan-15", "number": 15, "title": "Project Evaluation and Reflection", "status": "available", "summary": "Evaluasi proyek, refleksi belajar, dan implikasi industri."}], "ade": [{"id": "ade-01", "number": 1, "title": "Pengantar Rekayasa Data (Overview of Data Engineering)", "status": "available", "summary": "Definisi data & rekayasa data, DIKW, big data 8V, arsitektur pipeline, peran data engineer, dan 14 aktivitas kunci."}, {"id": "ade-02", "number": 2, "title": "Kategorisasi & Sumarisasi Data (Data Categorization and Summarization)", "status": "available", "summary": "Kategori struktur data, skala pengukuran (nominal, ordinal, interval, rasio), konteks data, statistik deskriptif, dan agregasi."}, {"id": "ade-03", "number": 3, "title": "Akuisisi & Preparasi Data (Data Acquisition and Preparation)", "status": "available", "summary": "Format data terbuka, akuisisi data, infrastruktur anotasi, pembersihan data, transformasi, integrasi, dan rekayasa fitur."}, {"id": "ade-04", "number": 4, "title": "Tata Kelola Data (Data Governance)", "status": "available", "summary": "Menjelaskan manajemen data, etika data, dan lisensi data."}, {"id": "ade-05", "number": 5, "title": "Masalah Umum pada Data (Common Data Issues)", "status": "available", "summary": "Mengidentifikasi anomaly, outlier, missing value, noise, duplikat, inkonsistensi."}, {"id": "ade-06", "number": 6, "title": "Transformasi Data & Rekayasa Fitur (Data Transformation & Feature Extraction)", "status": "available", "summary": "Menjelaskan rescaling, reduksi, diskretisasi, sampling, agregasi, normalisasi."}, {"id": "ade-07", "number": 7, "title": "Sistem Basis Data Relasional (Relational Database Management System)", "status": "available", "summary": "Menjelaskan konsep, arsitektur, dan komponen utama RDBMS."}, {"id": "ade-08", "number": 8, "title": "Normalisasi & Pemodelan Dimensional (Normalization & Dimensional Modelling)", "status": "available", "summary": "Menerapkan normalisasi hingga bentuk normal yang sesuai (1NF–BCNF)."}, {"id": "ade-09", "number": 9, "title": "ETL, ELT & Data Pipeline (ETL, ELT, and Data Pipelines)", "status": "available", "summary": "Menganalisis kebutuhan integrasi data."}, {"id": "ade-10", "number": 10, "title": "Basis Data Non-Tradisional 1: NoSQL (Non-traditional Data Engineering 1: NoSQL)", "status": "available", "summary": "Menjelaskan 4 tipe NoSQL: document, key-value, column-family, graph."}, {"id": "ade-11", "number": 11, "title": "Data Lake, Warehouse & Lakehouse (Data Lake, Warehouse & Lakehouse)", "status": "available", "summary": "Menjelaskan data mart, warehouse, lake, lakehouse."}, {"id": "ade-12", "number": 12, "title": "Pemrosesan Paralel & Terdistribusi (+ Tugas-2) (Parallel & Distributed Processing)", "status": "available", "summary": "Menjelaskan batch vs stream, in-memory, parallel computing."}, {"id": "ade-13", "number": 13, "title": "Keamanan, Kualitas & Skalabilitas Data (Data Security, Quality & Scalability)", "status": "available", "summary": "Menjelaskan enkripsi, kontrol akses, autentikasi, regulasi privasi."}]}, "content": {"ade-01": {"courseId": "ade", "sessionId": "ade-01", "eyebrow": "Modul 01 · M-059", "title": "Pengantar Rekayasa Data (Overview of Data Engineering)", "lead": "Memahami definisi data dan data engineering, piramida DIKW, karakteristik Big Data (8V), tantangan rekayasa, perbedaan peran profesional data, arsitektur pipeline, serta 14 aktivitas inti data engineer.", "sections": [{"id": "definisi", "label": "Definisi & Fondasi", "title": "1. Apa itu Data dan Rekayasa Data (Data Engineering)?", "image": {"src": "assets/images/ade/p1-dikw.jpg", "caption": "Piramida DIKW: Dari data mentah tanpa konteks menuju kebijakan (wisdom) melalui pemrosesan dan pemahaman."}, "body": ["Data didefinisikan sebagai representasi fakta, konsep, atau instruksi dalam bentuk terformalisasi yang cocok untuk komunikasi, interpretasi, atau pemrosesan oleh manusia maupun sistem otomatis (Hicks 1993, dikutip oleh Checkland dan Holwell 1998). DAMA (2021) menambahkan bahwa data adalah fakta individual yang disajikan dalam bentuk teks, angka, grafik, citra, audio, atau video yang berada di luar konteks dan belum memiliki makna inheren.", "Data Engineering adalah subdisiplin rekayasa perangkat lunak (software engineering) yang berfokus pada transportasi, transformasi, dan pengelolaan data. Jika IEEE mendefinisikan rekayasa perangkat lunak sebagai penerapan pendekatan yang sistematis, berdisiplin, dan terukur terhadap pengembangan, pengoperasian, dan pemeliharaan perangkat lunak, maka rekayasa data adalah penerapan prinsip perangkat lunak tersebut khusus untuk menangani pergerakan dan tata kelola data."], "callout": "Piramida DIKW: Data (fakta mentah) → Information (data berkonteks) → Knowledge (pemahaman pola & wawasan) → Wisdom (kemampuan mengambil keputusan terapan)."}, {"id": "ekonomi-data", "label": "Ekonomi Informasi", "title": "2. Data as the New Oil & Penggerak Ekonomi Digital", "image": {"src": "assets/images/ade/p1-data-never-sleeps.jpg", "caption": "Infografis Data Never Sleeps: Skala masif data yang diproduksi setiap menit di era ekonomi digital."}, "body": ["Minyak bumi menggerakkan ekonomi industri masa lalu dan bersifat terbatas (finite). Sebaliknya, data menggerakkan ekonomi informasi modern: jumlah pengetahuan yang diperoleh berbanding lurus dengan data yang dimiliki, di mana ekstraksi informasi membutuhkan pengumpulan, pemrosesan, dan analisis yang berkelanjutan.", "Studi kasus implementasi industri: Amazon merevolusi e-commerce melalui rekomendasi terpersonalisasi, anticipatory shipping, dan dynamic pricing. Netflix beralih dari rental DVD ke layanan streaming berbasis Big Data (termasuk sayembara algoritma $1 Juta USD pada 2006-2009). Platform media sosial seperti Facebook memanfaatkan pelacakan perilaku pengguna secara real-time untuk penargetan iklan presisi."], "callout": "Data Never Sleeps: miliaran pencarian, transaksi perbankan, streaming video, dan pertukaran pesan diproduksi setiap menit di seluruh dunia."}, {"id": "karakteristik-big-data", "label": "Karakteristik Data", "title": "3. Karakteristik Big Data: The 8 V's & Tantangan Rekayasa", "image": {"src": "assets/images/ade/p1-big-data-8v.jpg", "caption": "Karakteristik Big Data (The 8 V's): Dimensi tantangan volume, kecepatan, keberagaman, dan keamanan data."}, "body": ["Karakteristik Big Data dirangkum ke dalam 8V: Volume (besaran data sesuai kebutuhan), Velocity (kecepatan data masuk), Variety (sumber data heterogen), Variability (variasi laju data seiring waktu), Veracity (akurasi dan kebenaran data), Value (nilai bisnis saat data paling dibutuhkan), Visualization (kemampuan disajikan dalam format yang dipahami), dan Vulnerability (keamanan dan kerentanan data).", "Tantangan rekayasa pada Big Data meliputi: bagaimana mengakumulasi data dari beragam sumber berbeda, menyimpan dan memindahkan data raksasa dengan cepat, menangani data tidak terstruktur (unstructured data), menyaring data yang relevan, serta menjamin pencegahan kehilangan data (zero data loss)."], "callout": "Kebutuhan utama rekayasa data: menangani data skala produksi dengan kecepatan dan akurasi tinggi, serta mengotomatisasi pipeline tanpa langkah manual."}, {"id": "peran-profesi", "label": "Ekosistem Peran", "title": "4. Data Engineer vs Data Scientist vs Machine Learning Engineer", "image": {"src": "assets/images/ade/p1-roles.jpg", "caption": "Perbandingan Peran: Kolaborasi Data Engineer, Data Scientist, dan Machine Learning Engineer."}, "body": ["Sebagian besar Data Scientist menghabiskan hingga 80% waktunya untuk aktivitas data engineering jika fondasi sistem belum matang. Pembagian peran spesifik dalam organisasi modern:", "Data Engineer: Membangun dan mengoptimalkan sistem serta pipeline penanganan data bervolume besar, serta memastikan data bersih dan berkualitas tinggi siap diakses pemangku kepentingan.", "Data Scientist: Mengeksplorasi data di data warehouse/mart untuk menemukan pola bisnis, membuat hipotesis, dan melatih model analitik terbaik.", "Machine Learning Engineer: Mengambil model data science menuju tahap produksi, mengimplementasikan proses retraining otomatis, dan mengelola batch scoring serta real-time inference."], "callout": "Data pipeline menghubungkan sumber data dengan sistem target, mengotomatisasi alur hidup data dari penciptaan hingga analisis."}, {"id": "aktivitas-rekayasa", "label": "Aktivitas Inti", "title": "5. Spektrum Aktivitas Rekayasa Data Modern", "image": {"src": "assets/images/ade/p1-pipeline.jpg", "caption": "Arsitektur Data Pipeline: Dari sumber data terdistribusi menuju analytics-ready data mart dan warehouse."}, "body": ["Aktivitas kunci data engineer mencakup: (1) Ingestion & Extraction dari basis data transaksi, API, sensor IoT, dan web scraping; (2) Data Integration & Loading ke data warehouse atau data lake; (3) Processing Pipeline untuk streaming real-time maupun batch terjadwal; (4) Data Storage architecture (Data Lake untuk mentah/unstructured, Data Warehouse untuk terstruktur); (5) Scalable Architecture secara horizontal dan vertikal di cloud atau on-premise; (6) Parallel Processing dengan Apache Hadoop dan Spark; (7) Transformation & Data Validation untuk membersihkan duplikat, outlier, dan missing values.", "Selain infrastruktur dasar, data engineer bertanggung jawab atas: (8) Data Catalog & Metadata untuk melacak inventaris aset dan silsilah data (lineage); (9) Monitoring & Logging dengan mekanisme failover dan retry; (10) Performance Optimization melalui indexing, partisi, dan alokasi resource; (11) Data Sharing & Security dengan enkripsi dan Privacy Enhancing Technologies; (12) Compliance & Governance terhadap regulasi perlindungan data seperti GDPR, HIPAA, dan UU PDP No. 27/2022; serta (13) Workflow Orchestration menggunakan alat seperti Apache Airflow."], "callout": "Sertifikasi industri rujukan: Databricks Certified Data Engineer, Snowflake SnowPro, Google Cloud Professional Data Engineer, AWS Certified Data Engineer Associate, dan Microsoft Azure DP-203."}], "quiz": [{"question": "Menurut IEEE dan materi kuliah, apa definisi Data Engineering yang paling tepat?", "options": ["Subdisiplin ilmu komunikasi yang mempelajari penyebaran berita digital", "Subdisiplin rekayasa perangkat lunak yang berfokus pada transportasi, transformasi, dan pengelolaan data secara terukur", "Kegiatan manual memasukkan data spreadsheet ke dalam dokumen laporan", "Proses merancang tampilan antarmuka (UI) untuk aplikasi mobile"], "answer": 1, "explanation": "Data engineering adalah subdisiplin software engineering yang menerapkan pendekatan sistematis dan terukur khusus pada transportasi, transformasi, dan manajemen data."}, {"question": "Pada piramida DIKW, tingkatan yang tepat dari dasar hingga puncak adalah…", "options": ["Wisdom → Knowledge → Information → Data", "Data → Information → Knowledge → Wisdom", "Data → Knowledge → Information → Wisdom", "Information → Data → Wisdom → Knowledge"], "answer": 1, "explanation": "Alur DIKW dimulai dari Data mentah, diolah menjadi Information berkonteks, dipahami menjadi Knowledge, hingga diterapkan sebagai Wisdom."}, {"question": "Manakah di bawah ini yang merupakan salah satu dari 8 V karakteristik Big Data?", "options": ["Veracity, Variety, Velocity, Vulnerability", "Virtual, Validity, Vector, Variable", "Vanilla, Voltage, Value, Vibration", "Volume, Vertex, Version, View"], "answer": 0, "explanation": "8 V's Big Data meliputi Volume, Velocity, Variety, Variability, Veracity, Value, Visualization, dan Vulnerability."}, {"question": "Berapa persen rata-rata waktu yang dihabiskan data scientist untuk aktivitas rekayasa data jika infrastruktur pipeline belum matang?", "options": ["Sekitar 10%", "Sekitar 20%", "Sekitar 50%", "Sekitar 80%"], "answer": 3, "explanation": "Survei industri menunjukkan data scientist menghabiskan 80% waktunya untuk mengumpulkan, membersihkan, dan menyiapkan data (data engineering), dan hanya 20% untuk pemodelan."}, {"question": "Apa perbedaan utama tanggung jawab antara Data Engineer dan Machine Learning Engineer?", "options": ["Data Engineer membangun pipeline dan ketersediaan data bersih skala besar; ML Engineer membawa model ke production dan mengatur retraining", "Data Engineer hanya membuat grafik; ML Engineer membersihkan data tabel", "Data Engineer mengelola budget keuangan; ML Engineer menulis skrip database", "Keduanya adalah peran yang sepenuhnya sama tanpa perbedaan tugas"], "answer": 0, "explanation": "Data engineer fokus pada sistem pipeline, storage, dan ketersediaan data andal, sedangkan ML engineer fokus mengoperasikan dan mengotomatisasi siklus hidup model ML di lingkungan produksi."}]}, "ade-02": {"courseId": "ade", "sessionId": "ade-02", "eyebrow": "Modul 02 · M-059", "title": "Kategorisasi & Sumarisasi Data (Data Categorization and Summarization)", "lead": "Mengkategorikan data berdasarkan struktur, skala pengukuran statistik, serta konten dan konteks. Melakukan sumarisasi numerik, grafis, tabular, dan teknik agregasi data.", "sections": [{"id": "kategori-struktur", "label": "Struktur Data", "title": "1. Kategorisasi Berdasarkan Struktur Data & Dimensi", "image": {"src": "assets/images/ade/p2-structure.jpg", "caption": "Kategorisasi Struktur: Data terstruktur (tabel), semi-terstruktur (JSON/XML), dan tidak terstruktur (teks/media)."}, "body": ["Memahami kategori data sangat penting untuk tata kelola (governance), perancangan basis data, integrasi, dan analitik karena menentukan bagaimana data disimpan, diambil, dan diproses secara efisien.", "Kategori berdasarkan struktur: (1) Structured Data — data terorganisir rapi dalam format kaku seperti tabel baris dan kolom RDBMS; (2) Semi-Structured Data — data yang memiliki tag atau penanda hierarkis fleksibel tanpa skema kaku, seperti file JSON, XML, dan log server; (3) Unstructured Data — data tanpa skema terdefinisi seperti teks bebas dokumen, citra, audio, dan video.", "Dalam data tabular, kolom disebut sebagai Features (variabel atau atribut), sedangkan baris merepresentasikan Data Points (observasi individual). Konsep Dimensionality (dimensi data) didefinisikan dari total banyaknya fitur yang dimiliki suatu dataset."], "callout": "Tantangan dimensi: Semakin banyak fitur, semakin tinggi risiko curse of dimensionality yang dapat memperlambat kueri dan menurunkan performa analitik."}, {"id": "skala-pengukuran", "label": "Skala Statistik", "title": "2. Skala Pengukuran: Kualitatif vs Kuantitatif", "image": {"src": "assets/images/ade/p2-scales.jpg", "caption": "Tabel Skala Pengukuran: Perbedaan karakteristik, operasi valid, dan contoh skala Interval, Rasio, Ordinal, dan Nominal."}, "body": ["Data dikelompokkan berdasarkan skala pengukuran statistik menurut hierarki Stevens:", "Data Kategorikal (Kualitatif): (1) Skala Nominal — label atau nama tanpa urutan inheren (contoh: jenis kelamin, warna produk, status perkawinan). Operasi statistik yang diizinkan terbatas pada Modus dan persentil frekuensi. (2) Skala Ordinal — kategori yang memiliki urutan logis namun tanpa interval terukur yang konstan (contoh: peringkat 'rendah, sedang, tinggi', tingkat kepuasan, rating bintang). Operasi yang diizinkan meliputi Median dan persentil.", "Data Numerik (Kuantitatif): (1) Skala Interval — data numerik dengan interval antarnilai yang sama, namun TIDAK memiliki nilai nol mutlak (true zero) (contoh: suhu dalam Celsius atau Fahrenheit; 0°C bukan ketiadaan suhu). Operasi yang diizinkan meliputi aritmatika penjumlahan/pengurangan, Mean, dan Standar Deviasi. (2) Skala Rasio — data numerik dengan nilai nol sejati (true zero point) sehingga rasio perbandingan bermakna penuh (contoh: tinggi, berat, pendapatan, usia, kuantitas order). Seluruh operasi aritmatika dan rasio perkalian/pembagian valid."], "callout": "Aturan praktis: Nominal (kategori tanpa urutan) → Ordinal (berurutan) → Interval (selisih bermakna, nol semu) → Rasio (nol mutlak, perbandingan rasio valid)."}, {"id": "konten-konteks", "label": "Konten & Konteks", "title": "3. Kategori Berdasarkan Konten: Metadata, Master, Transaksional & Analitikal", "image": {"src": "assets/images/ade/p2-dimensions.jpg", "caption": "Fitur, Titik Data, dan Dimensi: Anatomi data tabular dan representasi baris-kolom."}, "body": ["Metadata vs Content Data: Metadata adalah 'data tentang data' yang mendeskripsikan atribut aset data (contoh: ukuran file, tanggal pembuatan, skema tabel, pemilik data, izin akses). Content data adalah substansi isi informasi itu sendiri (misalnya isi teks dokumen, angka transaksi, atau piksel citra).", "Klasifikasi data operasional organisasi: (1) Master Data — data entitas inti yang bersifat esensial dan konsisten lintas sistem operasional (contoh: data pelanggan, data produk, data mahasiswa, bagan akun); (2) Transactional Data — data yang tercipta dari aktivitas operasional transaksi harian (contoh: transaksi penjualan kasir, transfer perbankan, invoice); (3) Analytical Data — data historis dan ringkasan yang diturunkan dari data transaksional untuk keperluan laporan, evaluasi performa, dan pengambilan keputusan bisnis (BI dan data warehouse)."], "callout": "Pengelolaan Master Data (Master Data Management / MDM) yang andal mencegah duplikasi dan inkonsistensi entitas pada seluruh pipeline organisasi."}, {"id": "sumarisasi-deskriptif", "label": "Sumarisasi Numerik", "title": "4. Sumarisasi Statistik Deskriptif & Agregasi Data", "image": {"src": "assets/images/ade/p2-boxplot.jpg", "caption": "Anatomi Box Plot: Menampilkan nilai minimum, Q1, Median (Q2), Q3, maksimum, dan pencilan (outliers)."}, "body": ["Sumarisasi data bertujuan memadatkan dataset besar dan kompleks ke dalam wujud ringkas yang menonjolkan karakteristik serta pola utama tanpa kehilangan esensi informasi.", "Ukuran Pemusatan (Central Tendency): Mean (rata-rata aritmatika), Median (nilai tengah pemisah 50% data atas dan bawah), dan Mode (nilai dengan kemunculan terbanyak). Bila data miring (skewed) atau memiliki outlier ekstrem, gunakan Median sebagai tolok ukur yang lebih stabil dibanding Mean.", "Ukuran Penyebaran (Variability): Range (jangkauan nilai maks - min), Varians, Standar Deviasi (penyimpangan rata-rata dari mean), dan Interquartile Range (IQR = Q3 - Q1) yang mengukur sebaran 50% data tengah.", "Persentil dan Kuartil: Membagi data terurut menjadi persentase tertentu (Kuartil membagi menjadi 4 bagian: Q1 25%, Q2 50%/median, Q3 75%) untuk mengevaluasi sebaran dan batas outlier.", "Teknik Agregasi Data: Meliputi Grouping Operations (operasi 'GROUP BY' dalam SQL dan pandas untuk menghitung metrik per kategori) dan Time Series Summaries (analisis deret waktu menggunakan moving average, cumulative sum, dan seasonal decomposition)."], "callout": "Rumus Pagar Outlier Tukey: Q1 - 1.5 * IQR (batas bawah) dan Q3 + 1.5 * IQR (batas atas). Nilai di luar rentang ini dianggap sebagai pencilan (outlier)."}, {"id": "metode-grafis-tabular", "label": "Grafis & Tabular", "title": "5. Metode Grafis dan Tabular dalam Sumarisasi", "image": {"src": "assets/images/ade/p2-choose-chart.jpg", "caption": "Panduan Pemilihan Grafik: Menentukan visualisasi terbaik antara Bar Chart, Pie Chart, Histogram, atau Scatter Plot."}, "body": ["Metode Visualisasi Grafis: (1) Histogram — menyajikan distribusi frekuensi data numerik ke dalam kelompok bin berkelanjutan; (2) Box Plot (Box-and-Whisker) — merangkum nilai minimum, Q1, median, Q3, maksimum, dan titik-titik pencilan (outlier) untuk mendeteksi kemiringan distribusi; (3) Scatter Plot — menampilkan relasi dan pola korelasi antara dua variabel numerik; (4) Bar Chart — ideal untuk membandingkan frekuensi atau total per kategori diskrit; (5) Pie Chart — hanya cocok untuk menggambarkan proporsi bagian dari keseluruhan dengan sedikit kategori (≤ 5 kategori).", "Metode Ringkasan Tabular: (1) Frequency Tables — menyajikan daftar frekuensi kemunculan tiap kategori data secara langsung; (2) Pivot Tables — memungkinkan agregasi data multidimensi lintas kategori dan waktu (seperti merangkum total penjualan berdasarkan wilayah dan kategori produk secara simultan)."], "callout": "Panduan memilih visualisasi: Distribusi 1 variabel numerik → Histogram/Boxplot; Relasi 2 variabel numerik → Scatter plot; Kategori diskrit → Bar chart."}], "quiz": [{"question": "Suhu tubuh sebesar 37°C termasuk ke dalam skala pengukuran statistik apa?", "options": ["Skala Nominal", "Skala Ordinal", "Skala Interval", "Skala Rasio"], "answer": 2, "explanation": "Suhu Celsius termasuk skala Interval karena memiliki interval terukur yang sama, tetapi tidak memiliki nilai nol mutlak (0°C bukan berarti tidak ada suhu sama sekali)."}, {"question": "Mengapa Median lebih disarankan dibanding Mean saat menyajikan ringkasan data yang memiliki outlier ekstrem?", "options": ["Karena Median selalu menghasilkan angka bulat", "Karena Median tidak terpengaruh oleh nilai ekstrem yang sangat besar atau kecil (robust)", "Karena Mean membutuhkan komputasi yang dilarang pada Big Data", "Karena rumus Median hanya berlaku untuk data kategorikal"], "answer": 1, "explanation": "Median adalah ukuran pemusatan yang tahan (robust) terhadap pencilan (outlier) dan distribusi data yang condong (skewed), sedangkan Mean sangat sensitif terhadap nilai ekstrem."}, {"question": "Data pelanggan seperti Nama, NIK, dan Alamat yang menjadi entitas inti bisnis dan jarang berubah diklasifikasikan sebagai…", "options": ["Transactional Data", "Master Data", "Analytical Data", "Metadata saja"], "answer": 1, "explanation": "Master Data adalah data entitas inti organisasi (pelanggan, produk, pemasok) yang bersifat esensial bagi operasi harian dan menjadi acuan bersama antarsistem."}, {"question": "Visualisasi grafik mana yang paling efektif untuk melihat korelasi antara dua variabel numerik?", "options": ["Pie Chart", "Histogram", "Scatter Plot", "Frequency Table"], "answer": 2, "explanation": "Scatter Plot memetakan titik-titik data pada sumbu X dan Y, sehingga hubungan korelasi, tren, dan sebaran bivariat terlihat secara visual."}, {"question": "Kapan penggunaan Pie Chart dianggap kurang tepat dalam penyajian data?", "options": ["Ketika kategori data berjumlah banyak (> 5) dan proporsinya hampir seragam", "Ketika data hanya terdiri dari dua kategori", "Ketika data merepresentasikan persentase total 100%", "Ketika ingin membandingkan nilai pria vs wanita"], "answer": 0, "explanation": "Pie chart sulit dibaca manusia jika memiliki banyak kategori kecil atau perbedaan sudut irisan sangat tipis; untuk kondisi tersebut Bar Chart jauh lebih unggul."}]}, "ade-03": {"courseId": "ade", "sessionId": "ade-03", "eyebrow": "Modul 03 · M-059", "title": "Akuisisi & Preparasi Data (Data Acquisition and Preparation)", "lead": "Standar format file data, metode akuisisi dan elisitasi kebutuhan data, infrastruktur anotasi, pembersihan data, transformasi, integrasi, resampling, serta teknik rekayasa fitur (feature engineering).", "sections": [{"id": "format-data", "label": "Standar Format", "title": "1. Rekomendasi Format Data Terbuka vs Format Proprietary", "image": {"src": "assets/images/ade/p3-formats.jpg", "caption": "Tabel Rekomendasi Format: Perbandingan format data terbuka yang direkomendasikan vs format proprietary yang tidak direkomendasikan."}, "body": ["Pemilihan format data menentukan keberlanjutan arsip, portabilitas, dan kemudahan pemrosesan pada pipeline data:", "Dokumen Teks: Format yang direkomendasikan adalah Unicode text (.txt), PDF/A (.pdf), dan OpenDocument Text (.odt). Format seperti Microsoft Word (.doc, .docx) dan Rich Text (.rtf) tidak direkomendasikan karena bersifat proprietary dan bergantung pada lisensi vendor.", "Spreadsheet & Data Tabular: Direkomendasikan CSV (.csv) dan OpenDocument Spreadsheet (.ods). Format Microsoft Excel (.xls, .xlsx) dan PDF tabular tidak direkomendasikan untuk pipeline analitik langsung.", "Database: Direkomendasikan ekspor SQL dump (.sql) dan CSV (.csv). Hindari Microsoft Access (.mdb) atau format tertutup lainnya.", "Data Spasial / GIS: Direkomendasikan GeoJSON (.json). Hindari format Shapefile (.shp) atau Esri Geodatabase (.gdb) bila memerlukan interoperabilitas terbuka.", "Media Gambar & Video: Direkomendasikan format JPEG (.jpg/.jpeg), TIFF (.tiff), PNG (.png), dan SVG (.svg) untuk citra; Matroska (.mkv) untuk video terbuka."], "callout": "Format data terbuka (open standards) menjamin prinsip FAIR (Findable, Accessible, Interoperable, Reusable) dan mencegah vendor lock-in jangka panjang."}, {"id": "metode-akuisisi", "label": "Metode Akuisisi", "title": "2. Konsep Akuisisi Data & Elisitasi Kebutuhan", "image": {"src": "assets/images/ade/p3-requirements.jpg", "caption": "Tahapan Kebutuhan Data: Dari identifikasi pemangku kepentingan hingga Source-to-Target mapping."}, "body": ["Definisi Akuisisi Data: Proses atau kegiatan mengamati fenomena alam, sosial, atau teknis secara langsung maupun tidak langsung menggunakan peralatan/instrumen tertentu untuk menghasilkan data yang dapat diproses komputer demi menjawab pertanyaan tertentu.", "Aktivitas yang BUKAN Akuisisi Data: (1) Mengunduh dataset publik dari repositori internet; (2) Membeli dataset teknis dari data provider; (3) Meminta data yang dibagikan oleh rekan kerja; (4) Mengumpulkan data acak dari situs web tanpa instrumen observasi terkalibrasi.", "Metode Pengumpulan Data: Eksperimen laboratorium dan uji lapangan (field trials), survei kuesioner kuantitatif dan kualitatif, wawancara mendalam dan Focus Group Discussion (FGD), Web Scraping dan pemantauan media sosial secara terprogram, Sensor & IoT Data Collection (menghasilkan data presisi tinggi namun memerlukan instrumen mahal), serta Crowdsourcing-based data collection.", "Tahapan Elisitasi Kebutuhan Data: Mengidentifikasi dokumentasi proyek & sistem → Identifikasi pemangku kepentingan (stakeholders) → Wawancara terstruktur → Meringkas gap kebutuhan → Dokumentasi workflow informasi → Pembuatan matriks Fact/Qualifier → Harmonisasi semantik elemen data → Penyusunan pemetaan Source-to-Target (STTM)."], "callout": "Source-to-Target Mapping (STTM) adalah cetak biru teknis data engineer yang memetakan kolom sumber data asli ke tabel target di data warehouse."}, {"id": "anotasi-labeling", "label": "Anotasi Data", "title": "3. Infrastruktur Anotasi dan Pelabelan untuk Pembelajaran Mesin", "image": {"src": "assets/images/ade/p3-object-detection.jpg", "caption": "Anotasi Object Detection: Pelabelan bounding box untuk melatih model supervised learning."}, "body": ["Model Supervised Learning memerlukan data berlabel (annotated/labeled data) agar dapat dilatih. Meskipun pelabelan data biasanya dikerjakan oleh pakar domain (domain experts/annotators), data engineer bertanggung jawab membangun sistem dan infrastruktur yang memfasilitasi proses pelabelan tersebut.", "Bentuk-bentuk anotasi populer meliputi: (1) Object Detection — pembuatan bounding box pada citra objek; (2) Named Entity Recognition (NER) — pelabelan entitas bernama pada teks kalimat (seperti nama orang, institusi, lokasi, atau tanggal); (3) Structure Tagging — penandaan hierarki struktur dan relasi pada dokumen semi-terstruktur.", "Tanggung jawab data engineer mencakup penyediaan platform anotasi yang mudah digunakan (misalnya alat anotasi web), penanganan alur ingest data mentah ke alat anotasi, serta ekstraksi hasil anotasi ke repositori pelatihan model."], "callout": "Alat anotasi yang baik memisahkan kompleksitas teknis pipeline dari pengguna awam, sehingga pakar domain dapat fokus memvalidasi akurasi label."}, {"id": "preprocessing-cleaning", "label": "Pembersihan Data", "title": "4. Preprocessing: Pembersihan, Transformasi, Integrasi & Resampling", "image": {"src": "assets/images/ade/p3-preprocessing.jpg", "caption": "Siklus Preprocessing Data: Tahapan sistematis dari data mentah hingga dataset terstruktur siap model."}, "body": ["Pembersihan Data (Data Cleaning): (1) Penanganan Nilai Hilang (Missing Values) melalui penghapusan (deletion baris/kolom) atau imputasi nilai pengganti (mean, median, mode, atau KNN imputation); (2) Penghapusan Duplikat untuk menjaga keunikan rekaman; (3) Deteksi & Penanganan Outlier menggunakan z-score atau rentang IQR, dengan keputusan pemangkasan (capping), transformasi log, atau investigasi; (4) Reduksi Noise melalui teknik binning, regresi, atau clustering.", "Transformasi Data: Konversi satuan agar konsisten, Normalisasi min-max untuk memetakan nilai ke rentang [0, 1], Standardisasi z-score untuk menghasilkan nilai berpusat pada mean 0 dan standar deviasi 1, transformasi logaritmik untuk mereduksi kemiringan distribusi, serta diskretisasi/binning variabel kontinu menjadi kategori berbasis equal-width atau equal-frequency.", "Integrasi & Resampling: Penggabungan data lintas sumber (joins dan concatenation), standardisasi format yang bertentangan, serta teknik penyeimbangan kelas data imbalans melalui Oversampling (duplikasi data minoritas atau algoritma SMOTE) dan Undersampling (pengurangan data mayoritas)."], "callout": "Aturan emas preprocessing: Lakukan transformasi fitting (scaler, encoder) HANYA pada data training, lalu terapkan transformasinya pada data testing untuk mencegah kebocoran data (data leakage)."}, {"id": "feature-engineering", "label": "Rekayasa Fitur", "title": "5. Feature Engineering: Encoding, Creation, Extraction & Selection", "image": {"src": "assets/images/ade/p3-feature-eng.jpg", "caption": "Alur Feature Engineering: Transformasi representasi fitur untuk memaksimalkan akurasi model ML."}, "body": ["Feature engineering adalah proses mentransformasikan data mentah menjadi fitur representatif yang meningkatkan performa model pembelajaran mesin.", "Categorical Encoding: One-Hot Encoding (mengubah kategori menjadi vektor biner terpisah), Label Encoding (mengubah kategori menjadi angka integer berurutan), serta Frequency atau Target Encoding (menggantikan kategori dengan statistik agregat target).", "Feature Creation: Pembuatan fitur turunan (contoh: total belanja = kuantitas x harga satuan), fitur polinomial & interaksi fitur non-linear, serta transformasi berbasis domain pengetahuan (seperti mengekstrak jam sibuk, hari kerja, dan musim dari kolom tanggal/waktu).", "Feature Extraction: Reduksi dimensi tinggi menggunakan PCA (Principal Component Analysis) atau t-SNE, representasi terkompresi dengan Autoencoder, serta vektorisasi teks ke bentuk numerik melalui TF-IDF, Word2Vec, GloVe, atau BERT.", "Feature Selection: (1) Filter Methods — uji statistik independen dari model (seperti Chi-Square, ANOVA, korelasi); (2) Wrapper Methods — mengevaluasi kombinasi fitur berdasarkan akurasi model latih (contoh: Recursive Feature Elimination / RFE); (3) Embedded Methods — seleksi fitur otomatis yang menjadi bagian dari algoritma pelatihan (contoh: regresi Lasso L1 regularization dan penalti pada Decision Trees).", "Tugas Praktikum: Pembuatan Colab notebook yang mengakuisisi dataset negara dari API restcountries.com, kurs valuta asing, cuaca ibukota, data COVID-19 disease.sh, menjalankan preprocessing/feature engineering, dan mengekspor hasil ke CSV beserta visualisasi ringkasannya."], "callout": "Tiga pilar seleksi fitur: Filter (cepat, berbasis statistik) → Wrapper (akurat namun komputasi berat) → Embedded (terintegrasi otomatis dalam model)."}], "quiz": [{"question": "Format file manakah yang paling direkomendasikan untuk penyimpanan data tabular terbuka jangka panjang?", "options": ["Microsoft Excel (.xlsx)", "Comma Separated Values (.csv) atau OpenDocument Spreadsheet (.ods)", "Rich Text Format (.rtf)", "PDF File (.pdf)"], "answer": 1, "explanation": "Format CSV dan ODS adalah standar terbuka yang tidak bergantung pada lisensi perangkat lunak berbayar dan dapat dibaca lintas platform."}, {"question": "Manakah kegiatan berikut yang BENAR-BENAR dikategorikan sebagai 'akuisisi data' menurut konsep rekayasa data?", "options": ["Mengunduh file zip dataset dari Kaggle", "Membeli dataset statistik dari agensi riset", "Mengamati fenomena suhu dan kelembaban langsung menggunakan instrumen sensor IoT terkalibrasi", "Menyalin tabel dari halaman Wikipedia secara manual"], "answer": 2, "explanation": "Akuisisi data adalah proses mengamati fenomena alam, sosial, atau teknis secara langsung/tidak langsung menggunakan instrumen pengukur untuk menghasilkan data yang dapat diproses komputer."}, {"question": "Apa perbedaan utama antara Normalisasi min-max dan Standardisasi z-score?", "options": ["Normalisasi menghasilkan rentang [0, 1], sedangkan Standardisasi menghasilkan nilai dengan mean 0 dan standar deviasi 1", "Normalisasi hanya untuk teks, sedangkan Standardisasi untuk gambar", "Normalisasi memerlukan penghapusan duplikat, sedangkan Standardisasi tidak", "Keduanya adalah rumus matematika yang menghasilkan nilai identik"], "answer": 0, "explanation": "Min-max scaling membatasi nilai pada skala [0, 1], sedangkan z-score mengubah data sehingga memiliki rata-rata 0 dan standar deviasi 1."}, {"question": "Metode seleksi fitur mana yang menggunakan uji statistik independen dari model pelatihan (seperti Chi-Square atau korelasi)?", "options": ["Wrapper Methods", "Filter Methods", "Embedded Methods", "Deep Learning Methods"], "answer": 1, "explanation": "Filter methods menyeleksi fitur menggunakan metrik statistik independen tanpa harus melatih model pembelajaran mesin secara berulang."}, {"question": "Teknik apa yang digunakan untuk menangani data kelas minoritas yang sangat sedikit pada klasifikasi imbalans dengan cara membuat data sintetis baru?", "options": ["Undersampling acak", "One-Hot Encoding", "SMOTE (Synthetic Minority Over-sampling Technique)", "Label Encoding"], "answer": 2, "explanation": "SMOTE adalah algoritma oversampling populer yang menciptakan sampel sintetis dari tetangga terdekat kelas minoritas untuk menyeimbangkan dataset."}]}, "ade-04": {"courseId": "ade", "sessionId": "ade-04", "eyebrow": "Modul 04 · M-059", "title": "Tata Kelola Data (Data Governance)", "lead": "Menjelaskan manajemen data, etika data, dan lisensi data. Menganalisis siklus DAMA-DMBOK: penyimpanan, backup, preservasi, berbagi. Merancang strategi manajemen data yang etis dan FAIR.", "sections": [{"id": "sec-1", "label": "Data Governance", "title": "1. Kerangka DAMA-DMBOK", "body": ["11 area: Data Governance, Architecture, Modeling, Storage, Security, Integration, Documents, Reference/Master Data, Warehousing/BI, Metadata, Quality. Governance adalah payung: kebijakan, peran (Data Owner, Steward, Custodian), dan audit."], "callout": "Bahan Bacaan: DAMA-DMBOK (2017) Ch.1-3; Engelhardt et al. FAIR Handbook (2022); Eryurek et al. (2021)"}, {"id": "sec-2", "label": "Data Governance", "title": "2. Etika & Lisensi", "body": ["Etika: consent, minimisasi data, keadilan (fairness), transparansi. Lisensi data terbuka: CC0 (public domain), CC-BY (wajib atribusi), CC-BY-SA, ODbL (OpenStreetMap). Data proprietary butuh DPA/MoU. Jangan scrape situs yang melarang di ToS/robots.txt."], "callout": ""}, {"id": "sec-3", "label": "Data Governance", "title": "3. Siklus & FAIR", "body": ["Plan (DMP) → Collect → Assure (QA) → Describe (metadata) → Preserve (repositori, DOI) → Discover/Share → Integrate/Reuse. FAIR: Findable (PID/DOI + metadata kaya), Accessible (protokol standar + kontrol akses), Interoperable (format terbuka + kosakata standar), Reusable (lisensi jelas + provenance)."], "callout": "Istilah Kunci: DAMA-DMBOK, Data Steward, CC0/CC-BY/ODbL, DMP, FAIR"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code># Contoh header metadata FAIR (disimpan bersama dataset)\ntitle: Indeks Kepuasan Mhs 2025\ncreator: Prodi Informatika S2\nlicense: CC-BY-4.0\npid: doi:10.xxxx/ade-2025-001\nformat: [parquet, csv]</code></pre>"}], "quiz": [{"question": "Tiga peran kunci tata kelola menurut DAMA…", "options": ["Owner, Steward, Custodian", "Admin, User, Guest", "Dev, Ops, QA", "CEO, CTO, CFO"], "answer": 0, "explanation": "Owner (akuntabilitas), Steward (kualitas), Custodian (teknis/ops)."}, {"question": "Lisensi yang membebaskan data ke domain publik…", "options": ["CC-BY-NC", "CC0", "Proprietary", "GPL"], "answer": 1, "explanation": "CC0 = no rights reserved; CC-BY wajib atribusi."}, {"question": "'A' dalam FAIR adalah…", "options": ["Accurate", "Accessible", "Archived", "Audited"], "answer": 1, "explanation": "Accessible: protokol standar + metadata walau data dibatasi aksesnya."}, {"question": "Dokumen rencana pengelolaan data penelitian disebut…", "options": ["DMP (Data Management Plan)", "ERD", "SOP lab", "MoU"], "answer": 0, "explanation": "DMP: apa data, format, penyimpanan, berbagi, preservasi."}, {"question": "Prinsip minimisasi data berarti…", "options": ["Kumpulkan data sebanyak mungkin", "Kumpulkan hanya data yang perlu & proporsional", "Hapus semua data", "Jual data"], "answer": 1, "explanation": "Etika + UU PDP: batasi pengumpulan pada tujuan yang sah."}]}, "ade-05": {"courseId": "ade", "sessionId": "ade-05", "eyebrow": "Modul 05 · M-059", "title": "Masalah Umum pada Data (Common Data Issues)", "lead": "Mengidentifikasi anomaly, outlier, missing value, noise, duplikat, inkonsistensi. Memilih teknik penanganan yang tepat per masalah.", "sections": [{"id": "sec-1", "label": "Common Data Issues", "title": "1. Taksonomi Masalah", "body": ["Missing (MCAR/MAR/MNAR), outlier vs anomaly (outlier = titik ekstrem; anomaly = pola menyimpang kontekstual), noise (kesalahan acak pengukuran), duplikat (exact & fuzzy), inkonsistensi format/satuan, data drift (distribusi berubah seiring waktu)."], "callout": "Bahan Bacaan: Han et al. (2022) Ch.3 Data Preprocessing"}, {"id": "sec-2", "label": "Common Data Issues", "title": "2. Deteksi", "body": ["Statistik: z-score, IQR fence (Q1−1.5·IQR), uji Grubbs. ML: Isolation Forest, LOF, autoencoder reconstruction error. Missing: profilkan pola (matrix plot). Duplikat: hashing + record linkage (Jaro-Winkler)."], "callout": ""}, {"id": "sec-3", "label": "Common Data Issues", "title": "3. Penanganan + Smoothing", "body": ["Missing: hapus (jika <5% & MCAR), imputasi (mean/median/mode, KNN, model-based), flag indikator missing. Outlier: winsorize, transform log, pisahkan untuk investigasi — jangan asal hapus. Noise: binning, moving average, Savitzky-Golay, wavelet. Selalu catat % data yang diubah."], "callout": "Istilah Kunci: MCAR/MAR/MNAR, IQR fence, Isolation Forest, Winsorize, Smoothing"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code>-- Deteksi outlier IQR per produk (PostgreSQL)\nWITH q AS (\n SELECT product_id, price,\n  PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY price) OVER (PARTITION BY category) AS q1,\n  PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY price) OVER (PARTITION BY category) AS q3\n FROM products)\nSELECT * FROM q WHERE price &lt; q1 - 1.5*(q3-q1) OR price &gt; q3 + 1.5*(q3-q1);</code></pre>"}], "quiz": [{"question": "Data hilang karena sensor rusak acak termasuk mekanisme…", "options": ["MCAR", "MAR", "MNAR", "Bukan missing"], "answer": 0, "explanation": "MCAR: hilang sepenuhnya acak, tidak terkait variabel lain."}, {"question": "Aturan pagar IQR untuk outlier…", "options": ["mean ± sd", "Q1−1.5·IQR dan Q3+1.5·IQR", "median ± 2", "min–max"], "answer": 1, "explanation": "Tukey fences — robust terhadap skew dibanding z-score."}, {"question": "Algoritma ML untuk deteksi anomali tak terawasi…", "options": ["Isolation Forest", "Linear regression", "K-means saja", "Naive Bayes"], "answer": 0, "explanation": "Isolation Forest mengisolasi anomali dengan sedikit partisi."}, {"question": "Teknik yang TIDAK tepat untuk outlier…", "options": ["Investigasi dulu sebelum hapus", "Winsorize", "Hapus massal tanpa catat", "Transform log"], "answer": 2, "explanation": "Outlier bisa jadi sinyal (fraud); hapus massal menghilangkan informasi."}, {"question": "Contoh smoothing deret waktu…", "options": ["Moving average", "One-hot encoding", "Hashing", "Indexing"], "answer": 0, "explanation": "Moving average meredam noise acak jangka pendek."}]}, "ade-06": {"courseId": "ade", "sessionId": "ade-06", "eyebrow": "Modul 06 · M-059", "title": "Transformasi Data & Rekayasa Fitur (Data Transformation & Feature Extraction)", "lead": "Menjelaskan rescaling, reduksi, diskretisasi, sampling, agregasi, normalisasi. Menganalisis PCA, binning, clustering untuk reduksi. Menerapkan teknik pada studi kasus.", "sections": [{"id": "sec-1", "label": "Data Transformation & Feature Extraction", "title": "1. Rescaling & Normalisasi", "body": ["Min-max scaling ke [0,1]; z-score standardization (mean 0, sd 1 — wajib untuk SVM, k-NN, PCA, neural net); robust scaling (median/IQR — tahan outlier); log/power transform untuk skew; one-hot vs ordinal/label encoding untuk kategorikal."], "callout": "Bahan Bacaan: Han et al. (2022) Ch.3; Leskovec et al. (2020) Ch.11-12"}, {"id": "sec-2", "label": "Data Transformation & Feature Extraction", "title": "2. Reduksi: Dimensionality, Numerosity, Compression", "body": ["Dimensionality: PCA (pilih komponen hingga 95% variance), feature selection (filter/wrapper/embedded). Numerosity: sampling (stratified!), agregasi (roll-up harian), histogram/sketch. Compression: Parquet + Snappy/ZSTD, dictionary encoding. Aturan: fit transform HANYA di data train, lalu apply ke test (hindari leakage)."], "callout": ""}, {"id": "sec-3", "label": "Data Transformation & Feature Extraction", "title": "3. Diskretisasi, Binning, Clustering, Sampling", "body": ["Binning: equal-width vs equal-frequency vs domain-driven. Discretization untuk aturan asosiasi/Naive Bayes. Clustering (k-means) sebagai fitur segmentasi. Sampling: random, stratified, reservoir untuk stream. Agregasi window untuk deret waktu (7-day avg)."], "callout": "Istilah Kunci: Min-max vs Z-score, PCA, Data leakage, Stratified sampling, Parquet"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code># Pola anti-leakage (scikit-learn)\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.decomposition import PCA\nsc = StandardScaler().fit(X_train)   # fit: train SAJA\nXtr = PCA(0.95).fit_transform(sc.transform(X_train))\nXte = sc.transform(X_test)           # test: transform SAJA</code></pre>"}], "quiz": [{"question": "Standardisasi z-score menghasilkan…", "options": ["Range [0,1]", "Mean 0, sd 1", "Median 0", "Distribusi uniform"], "answer": 1, "explanation": "z = (x−mean)/sd; wajib untuk algoritma berbasis jarak."}, {"question": "Kebocoran data (leakage) terjadi jika…", "options": ["Fit scaler memakai data test", "Memakai train-test split", "Normalisasi train saja", "Memakai cross-validation"], "answer": 0, "explanation": "Statistik test bocor ke train → evaluasi terlalu optimistis."}, {"question": "PCA memilih komponen berdasarkan…", "options": ["Nilai maksimum", "Proporsi varians dijelaskan", "Jumlah missing", "Alfabet"], "answer": 1, "explanation": "Umumnya pertahankan ~95% cumulative variance."}, {"question": "Equal-frequency binning berarti…", "options": ["Lebar interval sama", "Jumlah observasi tiap bin sama", "Bin acak", "Satu bin saja"], "answer": 1, "explanation": "Kebalikan dari equal-width; robust terhadap skew."}, {"question": "Format kolom terkompresi standar lakehouse…", "options": ["CSV", "Parquet", "TXT", "BMP"], "answer": 1, "explanation": "Parquet: columnar + encoding + Snappy/ZSTD."}]}, "ade-07": {"courseId": "ade", "sessionId": "ade-07", "eyebrow": "Modul 07 · M-059", "title": "Sistem Basis Data Relasional (Relational Database Management System)", "lead": "Menjelaskan konsep, arsitektur, dan komponen utama RDBMS. Mengevaluasi peran RDBMS dalam ekosistem data engineering modern (integritas, kinerja, skalabilitas).", "sections": [{"id": "sec-1", "label": "Relational Database Management System", "title": "1. Konsep & Arsitektur", "body": ["RDBMS: data sebagai relasi + constraint (PK, FK, UNIQUE, CHECK) + ACID (Atomicity, Consistency, Isolation, Durability). Komponen: parser/optimizer (rencana query), executor, storage engine (heap + B-tree index), buffer pool, WAL (write-ahead log), lock/concurrency manager (MVCC)."], "callout": "Bahan Bacaan: Elmasri & Navathe (2016) Ch.1-2, 17-19; Kleppmann (2017) Ch.7"}, {"id": "sec-2", "label": "Relational Database Management System", "title": "2. Integritas & Kinerja", "body": ["Normalisasi (Modul 8) menjaga integritas; index B-tree mempercepat lookup/filter/join tapi memperlambat write. EXPLAIN ANALYZE untuk membaca query plan. Isolasi transaksi: read committed vs repeatable read vs serializable — tradeoff konsistensi vs throughput."], "callout": ""}, {"id": "sec-3", "label": "Relational Database Management System", "title": "3. Peran Modern + Tugas-1", "body": ["RDBMS tetap jadi system of record OLTP; analitik berat di-offload ke warehouse/lakehouse via CDC. Justifikasi pemilihan: butuh join kompleks + ACID kuat → RDBMS (PostgreSQL); butuh skala tulis masif/skema fleksibel → NoSQL (Modul 11). TUGAS-1: Analisis & Visualisasi Data (dataset pilihan, EDA + dashboard, dinilai di Mg 7)."], "callout": "Istilah Kunci: ACID, MVCC, B-tree index, WAL, Query plan, CDC"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code>-- Index + lihat query plan\nCREATE INDEX idx_orders_customer_date ON orders(customer_id, order_date);\nEXPLAIN ANALYZE SELECT * FROM orders\nWHERE customer_id = 42 AND order_date &gt;= '2025-01-01';</code></pre>"}], "quiz": [{"question": "Huruf 'A' dalam ACID…", "options": ["Availability", "Atomicity", "Accuracy", "Audit"], "answer": 1, "explanation": "Atomicity: transaksi all-or-nothing."}, {"question": "Struktur indeks default kebanyakan RDBMS…", "options": ["Hash table", "B-tree", "Linked list", "Heap saja"], "answer": 1, "explanation": "B-tree: seimbang untuk range + point lookup."}, {"question": "WAL (Write-Ahead Log) menjamin…", "options": ["Kecepatan baca", "Durability (tahan crash)", "Kompresi", "Enkripsi"], "answer": 1, "explanation": "Tulis log dulu sebelum data page → bisa recovery."}, {"question": "Perintah untuk melihat rencana eksekusi query…", "options": ["EXPLAIN ANALYZE", "SHOW TABLES", "DESCRIBE", "VACUUM"], "answer": 0, "explanation": "Rencana: seq scan vs index scan, cost, rows."}, {"question": "Isolasi tertinggi (paling konsisten, paling lambat)…", "options": ["Read uncommitted", "Read committed", "Repeatable read", "Serializable"], "answer": 3, "explanation": "Serializable mencegah anomaly konkurensi dengan harga throughput."}]}, "ade-08": {"courseId": "ade", "sessionId": "ade-08", "eyebrow": "Modul 08 · M-059", "title": "Normalisasi & Pemodelan Dimensional (Normalization & Dimensional Modelling)", "lead": "Menerapkan normalisasi hingga bentuk normal yang sesuai (1NF–BCNF). Merancang star/snowflake schema: tabel fakta vs dimensi. Memvalidasi rancangan dari sisi integritas, efisiensi, analitik.", "sections": [{"id": "sec-1", "label": "Normalization & Dimensional Modelling", "title": "1. Normalisasi (OLTP)", "body": ["1NF: atomik, tanpa repeating group. 2NF: non-key bergantung penuh pada seluruh PK (hilangkan partial dependency). 3NF: tanpa transitive dependency. BCNF: setiap determinan adalah superkey. Denormalisasi terkontrol boleh untuk baca-berat — dengan alasan tertulis."], "callout": "Bahan Bacaan: Kimball & Ross (2013) Ch.1-4; Elmasri & Navathe (2016) Ch.14-15"}, {"id": "sec-2", "label": "Normalization & Dimensional Modelling", "title": "2. Model Dimensional (OLAP)", "body": ["Fakta = ukuran numerik + FK (mis. sales_amount, qty) — grain harus eksplisit (satu baris = satu order line). Dimensi = konteks (waktu, produk, pelanggan, SCD tipe 1/2 untuk histori). Star (dimensi flat, cepat) vs Snowflake (dimensi ternormalisasi, hemat)."], "callout": ""}, {"id": "sec-3", "label": "Normalization & Dimensional Modelling", "title": "3. Validasi", "body": ["Checklist: grain konsisten? SCD tepat? surrogate key untuk dimensi? conformed dimensions lintas datamart? Uji dengan 3–5 query bisnis nyata + EXPLAIN."], "callout": "Istilah Kunci: 1NF/2NF/3NF/BCNF, Grain, Fact vs Dimension, Star vs Snowflake, SCD"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code>-- Star schema minimal\nCREATE TABLE dim_date(date_key INT PRIMARY KEY, d DATE, month INT, year INT);\nCREATE TABLE dim_product(product_key SERIAL PRIMARY KEY, sku TEXT, category TEXT);\nCREATE TABLE fact_sales(order_line_id BIGINT PRIMARY KEY,\n date_key INT REFERENCES dim_date, product_key INT REFERENCES dim_product,\n qty INT, amount NUMERIC(12,2));</code></pre>"}], "quiz": [{"question": "Tabel melanggar 1NF jika…", "options": ["Ada kolom non-atomik / repeating group", "Ada PK", "Sudah ada FK", "Ada index"], "answer": 0, "explanation": "1NF: tiap sel atomik, tiap baris unik."}, {"question": "2NF menghilangkan…", "options": ["Transitive dependency", "Partial dependency", "Multivalued", "Join"], "answer": 1, "explanation": "Non-key harus bergantung penuh pada seluruh PK komposit."}, {"question": "Dalam star schema, tabel fakta berisi…", "options": ["Atribut deskriptif", "Ukuran numerik + FK ke dimensi", "Hanya teks", "Metadata"], "answer": 1, "explanation": "Fakta = measures; dimensi = konteks."}, {"question": "Grain yang baik harus…", "options": ["Ambigu", "Dideklarasikan eksplisit per baris", "Berubah-ubah", "Disembunyikan"], "answer": 1, "explanation": "Mis. 'satu baris = satu order line'."}, {"question": "SCD Tipe 2 digunakan untuk…", "options": ["Timpa histori", "Simpan histori perubahan dimensi sebagai baris baru", "Hapus dimensi", "Arsip file"], "answer": 1, "explanation": "Tipe 1 = overwrite; Tipe 2 = histori penuh."}]}, "ade-09": {"courseId": "ade", "sessionId": "ade-09", "eyebrow": "Modul 09 · M-059", "title": "ETL, ELT & Data Pipeline (ETL, ELT, and Data Pipelines)", "lead": "Menganalisis kebutuhan integrasi data. Merancang alur ETL/ELT dan pipeline yang efisien. Mengevaluasi rancangan dari sisi kualitas data & kinerja.", "sections": [{"id": "sec-1", "label": "ETL, ELT, and Data Pipelines", "title": "1. ETL vs ELT", "body": ["ETL: Transform sebelum Load (cocok untuk warehouse klasik + aturan ketat). ELT: Load mentah dulu ke lake/warehouse lalu Transform di dalam (cocok untuk big data + fleksibilitas, mis. dbt di BigQuery/Snowflake). Pola medallion: Bronze (mentah) → Silver (bersih) → Gold (agregat bisnis)."], "callout": "Bahan Bacaan: Reis & Housley (2022) Ch.8-10; Doan et al. (2012) Ch.5-6"}, {"id": "sec-2", "label": "ETL, ELT, and Data Pipelines", "title": "2. Anatomi Pipeline", "body": ["Ingest → Validate (Great Expectations: not-null, unique, range) → Transform (idempotent!) → Load (upsert/merge, SCD) → Orchestrate (Airflow/Prefect: retry, SLA, alerting) → Observe (data docs, freshness, volume, lineage dengan OpenLineage)."], "callout": ""}, {"id": "sec-3", "label": "ETL, ELT, and Data Pipelines", "title": "3. Kualitas & Kinerja", "body": ["Idempotensi: rerun aman. Incremental vs full load (watermark). Partisi berdasarkan tanggal. Evaluasi: data quality gates lolos? SLA terpenuhi? biaya compute? RPO/RTO backup?"], "callout": "Istilah Kunci: ETL vs ELT, Medallion, Idempotent, Orchestration, Data observability"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code>-- Contoh ELT: transform di dalam warehouse (dbt-style)\nCREATE OR REPLACE VIEW gold.daily_revenue AS\nSELECT d.year, d.month, SUM(f.amount) AS revenue\nFROM fact_sales f JOIN dim_date d USING (date_key)\nGROUP BY 1, 2;</code></pre>"}], "quiz": [{"question": "Perbedaan ETL vs ELT…", "options": ["Sama saja", "ETL transform sebelum load; ELT load mentah dulu lalu transform di platform target", "ELT lebih lama selalu", "ETL tanpa extract"], "answer": 1, "explanation": "ELT memanfaatkan compute warehouse/lake modern (dbt)."}, {"question": "Lapisan 'Silver' pada medallion…", "options": ["Data mentah", "Data bersih/tervalidasi", "Agregat bisnis final", "Backup tape"], "answer": 1, "explanation": "Bronze mentah → Silver bersih → Gold bisnis."}, {"question": "Sifat pipeline yang aman di-rerun disebut…", "options": ["Idempotent", "Volatile", "Random", "Blocking"], "answer": 0, "explanation": "Rerun menghasilkan state akhir sama."}, {"question": "Contoh data quality gate…", "options": ["Cek not-null, unique, range sebelum load", "Hapus log", "Matikan alert", "Full load selalu"], "answer": 0, "explanation": "Validasi dengan Great Expectations / dbt tests."}, {"question": "Fungsi orchestrator (Airflow)…", "options": ["Menyimpan data", "Menjadwalkan, retry, SLA & alerting DAG", "Melatih model", "Membuat ERD"], "answer": 1, "explanation": "Orkestrasi依存 + observability pipeline."}]}, "ade-10": {"courseId": "ade", "sessionId": "ade-10", "eyebrow": "Modul 10 · M-059", "title": "Basis Data Non-Tradisional 1: NoSQL (Non-traditional Data Engineering 1: NoSQL)", "lead": "Menjelaskan 4 tipe NoSQL: document, key-value, column-family, graph. Menganalisis perbedaan vs relasional + tradeoff CAP/PACELC. Memilih jenis yang tepat per kebutuhan.", "sections": [{"id": "sec-1", "label": "Non-traditional Data Engineering 1: NoSQL", "title": "1. Empat Tipe", "body": ["Document (MongoDB: JSON fleksibel, katalog produk). Key-Value (Redis: session/cache, TTL). Column-family (Cassandra/HBase: tulis masif time-series, partisi). Graph (Neo4j: relasi kompleks — fraud, rekomendasi, knowledge graph)."], "callout": "Bahan Bacaan: Sadalage & Fowler (2012); Kleppmann (2017) Ch.2"}, {"id": "sec-2", "label": "Non-traditional Data Engineering 1: NoSQL", "title": "2. vs Relasional + Teorema CAP", "body": ["Relasional: skema kaku + join kuat + ACID. NoSQL: skema fleksibel + skala horizontal + BASE (Basically Available, Soft state, Eventually consistent). CAP: saat partisi jaringan, pilih Consistency atau Availability. PACELC melengkapi untuk kondisi normal (latency vs consistency)."], "callout": ""}, {"id": "sec-3", "label": "Non-traditional Data Engineering 1: NoSQL", "title": "3. Panduan Pilih", "body": ["Butuh join ad-hoc + integritas → RDBMS. Dokumen heterogen → Document. Lookup super-cepat → Key-Value. Time-series tulis masif → Column. Jelajah relasi multi-hop → Graph. Polyglot persistence (campuran) itu normal."], "callout": "Istilah Kunci: Document/Key-Value/Column/Graph, CAP & PACELC, BASE vs ACID, Polyglot persistence"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code>// MongoDB: dokumen fleksibel (satu koleksi, skema bervariasi)\ndb.products.insertOne({ sku:\"A-1\", name:\"Kopi\", tags:[\"arabika\"],\n  specs:{ weight_g:200 }, price: 85000 })\n// Redis: cache sesi dengan TTL\n// SET session:42 \"....\" EX 3600</code></pre>"}], "quiz": [{"question": "MongoDB termasuk tipe…", "options": ["Key-value", "Document", "Column-family", "Graph"], "answer": 1, "explanation": "Dokumen JSON/BSON fleksibel per record."}, {"question": "Redis paling cocok untuk…", "options": ["Graph traversal", "Cache/session lookup super-cepat", "Full-text join kompleks", "Data warehouse"], "answer": 1, "explanation": "In-memory key-value + TTL."}, {"question": "Cassandra adalah contoh…", "options": ["Document", "Column-family", "Graph", "Relasional"], "answer": 1, "explanation": "Tulis masif terdistribusi, partisi row-key."}, {"question": "Teorema CAP menyatakan saat partisi…", "options": ["Pilih C atau A", "Bisa semua sekaligus", "Tidak perlu partisi", "Hanya latency"], "answer": 0, "explanation": "Consistency vs Availability saat network partition."}, {"question": "Kasus paling cocok untuk graph DB…", "options": ["Katalog produk sederhana", "Deteksi fraud berbasis relasi multi-hop", "Log time-series", "Session cache"], "answer": 1, "explanation": "Traversal relasi dalam di Neo4j jauh lebih cepat dari join berlapis."}]}, "ade-11": {"courseId": "ade", "sessionId": "ade-11", "eyebrow": "Modul 11 · M-059", "title": "Data Lake, Warehouse & Lakehouse (Data Lake, Warehouse & Lakehouse)", "lead": "Menjelaskan data mart, warehouse, lake, lakehouse. Menganalisis kelebihan/kekurangan + contoh penerapan.", "sections": [{"id": "sec-1", "label": "Data Lake, Warehouse & Lakehouse", "title": "1. Definisi", "body": ["Warehouse: terstruktur, skema-on-write, optimal untuk BI/SQL (Snowflake, BigQuery). Lake: mentah multi-format, skema-on-read, murah (S3 + Parquet/Iceberg). Lakehouse: gabungan — lake murah + transaksi/ACID + SQL performan (Delta Lake, Iceberg, Hudi). Mart: subset warehouse per departemen."], "callout": "Bahan Bacaan: Kimball & Ross (2013) Ch.1; Dehghani (2022); Reis & Housley (2022) Ch.5"}, {"id": "sec-2", "label": "Data Lake, Warehouse & Lakehouse", "title": "2. Perbandingan", "body": ["Warehouse: kualitas & governance kuat, biaya storage/compute tinggi. Lake: fleksibel & murah, risiko jadi 'data swamp' tanpa katalog. Lakehouse: modern default untuk analitik + ML. Data Mesh (Dehghani): desentralisasi kepemilikan per domain + federated governance."], "callout": ""}, {"id": "sec-3", "label": "Data Lake, Warehouse & Lakehouse", "title": "3. Contoh", "body": ["Universitas: lake (log LMS mentah) → warehouse (dimensi mhs, fakta nilai) → mart (mart_akademik, mart_keuangan) → dashboard + early-warning DO. Format terbuka: Parquet + Iceberg agar antar-engine interoperable."], "callout": "Istilah Kunci: Schema-on-write vs on-read, Lakehouse, Delta/Iceberg/Hudi, Data mart, Data mesh"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code>-- Iceberg: time travel &amp; evolusi skema aman\n-- SELECT * FROM gold.mart_akademik FOR SYSTEM_TIME AS OF '2025-08-01';\nALTER TABLE lake.silver_logs ADD COLUMNS (prodi STRING);</code></pre>"}], "quiz": [{"question": "Schema-on-read adalah ciri…", "options": ["Warehouse", "Data lake", "OLTP", "Spreadsheet"], "answer": 1, "explanation": "Lake simpan mentah, skema saat dibaca."}, {"question": "Lakehouse menggabungkan…", "options": ["Lake murah + transaksi/ACID & SQL performan ala warehouse", "OLTP + email", "CSV + PDF", "FTP + blog"], "answer": 0, "explanation": "Delta/Iceberg/Hudi di atas object store."}, {"question": "Data mart adalah…", "options": ["Seluruh warehouse", "Subset warehouse per domain/departemen", "Data mentah", "Backup"], "answer": 1, "explanation": "Mis. mart_akademik, mart_keuangan."}, {"question": "Risiko 'data swamp'…", "options": ["Lake tanpa katalog/governance", "Warehouse mahal", "OLTP lambat", "Dashboard bagus"], "answer": 0, "explanation": "Tanpa metadata & quality gates, lake tak usable."}, {"question": "Format tabel terbuka untuk lakehouse…", "options": ["Parquet + Iceberg/Delta", "BMP", "MP3", "DOCX"], "answer": 0, "explanation": "Interoperabel antar-engine (Spark, Trino, Flink)."}]}, "ade-12": {"courseId": "ade", "sessionId": "ade-12", "eyebrow": "Modul 12 · M-059", "title": "Pemrosesan Paralel & Terdistribusi (+ Tugas-2) (Parallel & Distributed Processing)", "lead": "Menjelaskan batch vs stream, in-memory, parallel computing. Menganalisis tradeoff tiap teknik + skenario penggunaan. Tugas-2: Analisis & Perancangan Basis Data.", "sections": [{"id": "sec-1", "label": "Parallel & Distributed Processing", "title": "1. Batch vs Stream", "body": ["Batch (Spark, MapReduce): throughput tinggi, latency menit–jam — cocok untuk ETL harian, training ML. Stream (Kafka + Flink/Spark Streaming): latency detik — cocok untuk fraud detection, monitoring. Lambda (batch+speed layer) vs Kappa (semua sebagai stream). Exactly-once butuh idempotent sink."], "callout": "Bahan Bacaan: Kleppmann (2017) Ch.8-11; Chambers & Zaharia (2018); Buyya et al. (2016)"}, {"id": "sec-2", "label": "Parallel & Distributed Processing", "title": "2. In-Memory & Paralel", "body": ["In-memory (Spark RDD/DataFrame, Redis) menghindari I/O disk berulang — 10–100x untuk iteratif (ML). Paralelisme: partisi data (hash/range), shuffle mahal — minimalkan. Amdahl's law: speedup terbatas oleh bagian sekuensial."], "callout": ""}, {"id": "sec-3", "label": "Parallel & Distributed Processing", "title": "3. Tugas-2", "body": ["TUGAS-2 (30%): Analisis & Perancangan Basis Data — pilih kasus (mis. akademik), rancang OLTP ternormalisasi + star schema + pipeline ETL/ELT + justifikasi NoSQL/lakehouse bila relevan. Kriteria: kebenaran konsep, kelengkapan rancangan, kualitas analisis, presentasi."], "callout": "Istilah Kunci: Batch vs Stream, Lambda vs Kappa, Exactly-once, Shuffle, In-memory"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code># Spark: batch agregat paralel (in-memory)\nfrom pyspark.sql import functions as F\ndf = spark.read.parquet(\"lake/silver/orders/\")\nrev = (df.groupBy(\"date\").agg(F.sum(\"amount\").alias(\"revenue\"))\n         .orderBy(\"date\"))\nrev.write.mode(\"overwrite\").parquet(\"lake/gold/daily_revenue/\")</code></pre>"}], "quiz": [{"question": "Streaming cocok untuk…", "options": ["Laporan bulanan", "Deteksi fraud real-time", "Arsip tahunan", "Backup tape"], "answer": 1, "explanation": "Latency detik via Kafka + Flink."}, {"question": "Arsitektur Kappa…", "options": ["Batch + speed layer", "Semua diperlakukan sebagai stream", "Tanpa data", "Hanya SQL"], "answer": 1, "explanation": "Satu pipeline stream; Lambda mempertahankan dua layer."}, {"question": "Exactly-once membutuhkan…", "options": ["Sink idempotent + checkpoint", "Hapus checkpoint", "Random offset", "Tanpa retry"], "answer": 0, "explanation": "Agar retry tidak menggandakan efek."}, {"question": "Operasi Spark paling mahal…", "options": ["Map", "Filter", "Shuffle", "Cache"], "answer": 2, "explanation": "Shuffle memindahkan data antar-node via jaringan/disk."}, {"question": "Keuntungan in-memory (Spark)…", "options": ["Hindari I/O disk berulang untuk iteratif/ML", "Selalu lebih murah", "Tanpa RAM", "Tanpa partisi"], "answer": 0, "explanation": "10–100x untuk workload iteratif."}]}, "ade-13": {"courseId": "ade", "sessionId": "ade-13", "eyebrow": "Modul 13 · M-059", "title": "Keamanan, Kualitas & Skalabilitas Data (Data Security, Quality & Scalability)", "lead": "Menjelaskan enkripsi, kontrol akses, autentikasi, regulasi privasi. Menganalisis mekanisme kontrol + menerapkan optimasi performa.", "sections": [{"id": "sec-1", "label": "Data Security, Quality & Scalability", "title": "1. Keamanan & Privasi", "body": ["Enkripsi: at-rest (AES-256) + in-transit (TLS 1.2+). Hash password dengan bcrypt/Argon2 (jangan MD5/SHA1 polos). Kontrol akses: RBAC + least privilege; masking/tokenisasi PII; audit log. Regulasi: UU PDP No. 27/2022 (Indonesia) — consent, hak hapus, breach notification; padanan: GDPR."], "callout": "Bahan Bacaan: Kleppmann (2017) Ch.10; Eryurek et al. (2021); UU PDP No.27/2022"}, {"id": "sec-2", "label": "Data Security, Quality & Scalability", "title": "2. Kualitas (lanjutan gov.)", "body": ["Dimensi: accuracy, completeness, consistency, timeliness, validity, uniqueness. Implementasikan quality gates di pipeline (tolak/karantina batch gagal) + SLO (mis. freshness < 1 jam, completeness > 99%)."], "callout": ""}, {"id": "sec-3", "label": "Data Security, Quality & Scalability", "title": "3. Skalabilitas & Optimasi", "body": ["Skala vertikal vs horizontal; partisi + indeks + materialized view; caching; kompresi kolom (Parquet); autoscaling. Ukur sebelum optimasi: EXPLAIN, profiling, benchmark. UAS = Hasil Proyek (30%): demo pipeline + laporan + presentasi."], "callout": "Istilah Kunci: AES-256/TLS, RBAC, Masking/Tokenisasi, UU PDP, SLO data quality"}, {"id": "code-snippet", "label": "Implementasi Praktis", "title": "Contoh Kode & Query", "body": ["Berikut adalah contoh kode atau kueri terkait topik modul ini:"], "callout": "<pre style=\"margin:0;overflow-x:auto;font-family:monospace;font-size:13px;line-height:1.5;\"><code>-- Kontrol akses + masking PII (PostgreSQL)\nCREATE ROLE analis LOGIN;\nGRANT SELECT ON gold.daily_revenue TO analis;\n-- masking: tampilkan hanya 4 digit akhir NIM\nSELECT CONCAT('***', RIGHT(nim, 4)) AS nim_masked, ipk FROM mart_akademik;</code></pre>"}], "quiz": [{"question": "Enkripsi data at-rest standar…", "options": ["ROT13", "AES-256", "Base64", "MD5"], "answer": 1, "explanation": "AES-256 + manajemen kunci (KMS); TLS untuk in-transit."}, {"question": "Password harus disimpan sebagai…", "options": ["Plaintext", "MD5", "bcrypt/Argon2 hash + salt", "Base64"], "answer": 2, "explanation": "Hash adaptif tahan brute-force/GPU."}, {"question": "Prinsip least privilege berarti…", "options": ["Semua akses penuh", "Akses minimum sesuai tugas (RBAC)", "Tanpa autentikasi", "Satu akun bersama"], "answer": 1, "explanation": "RBAC + review berkala + audit log."}, {"question": "UU PDP Indonesia…", "options": ["UU No. 27 Tahun 2022", "UU No. 1 Tahun 2000", "Perda parkir", "Tidak ada"], "answer": 0, "explanation": "Mengatur consent, hak subjek data, notifikasi breach."}, {"question": "Contoh SLO kualitas data…", "options": ["Freshness < 1 jam & completeness > 99%", "Server menyala", "Ada WiFi", "Dashboard berwarna"], "answer": 0, "explanation": "SLO terukur + quality gates otomatis."}]}, "pertemuan-01": {"courseId": "se4ds", "sessionId": "pertemuan-01", "eyebrow": "Session 01 · M-058", "title": "Introduction to Data-Driven Software Development", "lead": "Data-driven software development memanfaatkan analisis data, metrik operasional, dan feedback nyata untuk memandu setiap keputusan dalam rekayasa perangkat lunak.", "sections": [{"id": "definisi", "label": "Konsep Dasar", "title": "Mengapa Software Modern Membutuhkan Data", "body": ["Data-driven software development adalah praktik memanfaatkan analisis data dan metrik terukur untuk memandu perancangan, pengembangan, dan evolusi perangkat lunak.", "Pendekatan ini menekankan pentingnya penggunaan data dunia nyata untuk menginformasikan keputusan arsitektural, mengoptimalkan kinerja sistem, dan meningkatkan pengalaman pengguna secara berkelanjutan."], "callout": "Keputusan rekayasa yang dipandu oleh metrik dan data empiris selalu mengungguli asumsi spekulatif."}, {"id": "paradigma", "label": "Evolusi Arsitektur", "title": "Dari RDBMS Klasik ke Pendekatan Multi-Model", "image": {"src": "assets/images/se4ds/se4ds-01-paradigm.jpg", "caption": "Evolusi Arsitektur: Menempatkan data primer pada pusat aplikasi dengan basis data multi-model."}, "body": ["Selama empat dekade, perangkat lunak terbiasa menempatkan seluruh data ke dalam RDBMS terpusat. Namun saat ini, volume data yang eksponensial dan keberagaman tipe data (dokumen JSON, time-series, grafik) menuntut fleksibilitas baru.", "Sistem modern memperlakukan data sebagai entitas utama: pertukaran dokumen antarsistem, event streaming, dan database multi-model mempercepat siklus antara spesifikasi fitur hingga deployment ke production."], "callout": "Format semi-terstruktur seperti JSON telah menjadi bahasa pertukaran informasi utama antara layanan backend dan frontend."}, {"id": "ekosistem", "label": "Ekosistem", "title": "Menyatukan Software Engineering, Data Science, dan MLOps", "body": ["Software engineering menyediakan fondasi berupa SDLC, Agile, dan DevOps agar kode dapat diuji dan dirilis secara otomatis.", "Data Science dan Machine Learning menyuntikkan kapabilitas analitik dan prediksi. MLOps kemudian menyatukan keduanya agar model dapat beroperasi di production dengan monitoring latensi, deteksi data drift, dan integrasi berkelanjutan."], "callout": "Model AI tercanggih sekalipun tidak bernilai jika sistem engineering di sekelilingnya rapuh atau tidak mampu menangani data produksi."}], "quiz": [{"question": "Apa esensi utama dari data-driven software development?", "options": ["Menghindari penggunaan database", "Memanfaatkan metrik dan analisis data nyata untuk memandu keputusan pengembangan", "Menulis kode tanpa pengujian", "Hanya fokus pada pembuatan tampilan antarmuka"], "answer": 1, "explanation": "Data-driven development menggunakan data dan metrik empiris untuk mengoptimalkan performa, arsitektur, dan pengalaman pengguna."}, {"question": "Mengapa sistem modern banyak beralih ke format multi-model dan dokumen seperti JSON?", "options": ["Karena RDBMS sudah tidak bisa menyimpan data teks", "Untuk mengakomodasi variasi tipe data, volume besar, dan integrasi layanan yang lebih fleksibel", "Karena JSON memerlukan memori lebih sedikit dibanding biner", "Agar tidak perlu membuat backup data"], "answer": 1, "explanation": "Variasi data dan kebutuhan integrasi cepat menuntut fleksibilitas skema yang disediakan database multi-model dan format dokumen."}, {"question": "Apa peran MLOps dalam ekosistem perangkat lunak modern?", "options": ["Menghapus peran software engineer", "Menjembatani model Machine Learning ke lingkungan operasional production secara andal", "Mengganti seluruh sistem cloud dengan server lokal", "Hanya bertugas menulis dokumentasi proyek"], "answer": 1, "explanation": "MLOps mengotomatisasi deployment, monitoring, dan pemeliharaan model Machine Learning di lingkungan produksi."}, {"question": "Apa risiko jika keputusan rekayasa software hanya didasarkan pada intuisi tanpa data metrik?", "options": ["Biaya server otomatis menjadi gratis", "Fitur berisiko tidak menyelesaikan masalah nyata pengguna dan degradasi performa terlambat terdeteksi", "Waktu kompilasi kode selalu lebih cepat", "Model otomatis mencapai akurasi 100%"], "answer": 1, "explanation": "Tanpa metrik observabilitas dan data pengguna, tim tidak dapat memvalidasi apakah solusi yang dibangun tepat sasaran dan berkinerja baik."}, {"question": "Prinsip apa dari DevOps yang diadopsi ke dalam MLOps?", "options": ["Manual deployment mingguan", "Continuous Integration, Continuous Delivery (CI/CD), dan otomasi monitoring", "Menghilangkan tahap testing agar cepat rilis", "Menyimpan kode tanpa version control"], "answer": 1, "explanation": "CI/CD dan otomasi monitoring adalah pilar utama DevOps yang diperluas ke MLOps untuk menangani data dan model pipeline."}]}, "pertemuan-02": {"courseId": "se4ds", "sessionId": "pertemuan-02", "eyebrow": "Session 02 · M-058", "title": "Fundamentals of Software Development", "lead": "Model machine learning baru menjadi produk ketika ia ditopang oleh proses software yang dapat direncanakan, diuji, dan dipelihara.", "sections": [{"id": "fondasi", "label": "Fondasi software", "title": "Software development bukan sekadar menulis kode", "body": ["Software development adalah proses terencana untuk menghasilkan perangkat lunak berkualitas dengan biaya dan waktu yang masuk akal. Kode hanyalah salah satu bagian dari proses itu.", "Dalam konteks data science, proses ini mencakup memahami masalah, menyiapkan data, melatih model, mengevaluasi hasil, lalu membungkus model menjadi layanan yang dapat digunakan pengguna."], "callout": "Pertanyaan engineering yang penting: apakah solusi ini dapat diulang, diuji, diamati, dan diubah tanpa merusak bagian lain?"}, {"id": "sdlc", "label": "SDLC & OOP", "title": "SDLC memberi ritme, OOP memberi struktur", "body": ["Software Development Life Cycle (SDLC) membantu tim bergerak dari perencanaan, analisis, desain, implementasi, pengujian, hingga pemeliharaan. Model Waterfall menekankan tahapan berurutan, sedangkan Agile dan Kanban menerima perubahan melalui iterasi pendek.", "Empat ide OOP yang relevan untuk pipeline data adalah abstraction, encapsulation, inheritance, dan polymorphism. Dengan abstraction, detail preprocessing dapat disembunyikan di balik antarmuka yang jelas. Encapsulation menjaga data dan operasi terkait tetap bersama."], "callout": "Pipeline yang baik memisahkan tanggung jawab: data preparation, training, evaluation, dan inference tidak bercampur menjadi satu skrip panjang."}, {"id": "validasi", "label": "Validasi model", "title": "Mengukur apakah model dapat mengenali data baru", "body": ["Pada hold-out split, 1.000 baris dapat dibagi menjadi 800 baris untuk training dan 200 baris untuk testing. Training digunakan untuk belajar; testing disimpan untuk mengukur kemampuan generalisasi.", "Pada 10-fold cross-validation, data dibagi menjadi sepuluh bagian. Setiap putaran memakai sembilan bagian untuk training dan satu bagian untuk validasi. Sepuluh hasil kemudian dirata-ratakan sehingga penilaian tidak bergantung pada satu pembagian saja."], "callout": "Gap akurasi training dan testing yang besar adalah sinyal untuk menyelidiki overfitting. Gap kecil belum otomatis menjamin model baik, tetapi merupakan petunjuk yang lebih sehat."}, {"id": "pipeline", "label": "ML ke aplikasi", "title": "Model adalah komponen, bukan seluruh produk", "body": ["Alur kerja dimulai dari dataset, pembagian data, training, dan evaluasi. Setelah model dipilih, model dapat disimpan dalam format yang dapat dimuat kembali oleh aplikasi.", "Software engineering kemudian mengurus API, validasi input, latency, logging, deployment, dan monitoring. Saat aplikasi menerima data baru, proses ini disebut inference. Model harus diuji bukan hanya di notebook, tetapi juga ketika digunakan oleh sistem nyata."], "callout": "Akurasi 98% dapat menipu pada data imbalance. Selalu lihat precision, recall, dan F1-score sesuai risiko kesalahan pada kasus yang sedang dibangun."}, {"id": "ringkas", "label": "Takeaways", "title": "Checklist sebelum model dipakai", "body": ["Tanyakan tiga hal: apakah model overfit, apakah model underfit, dan bagaimana performanya pada unseen data? Lalu pastikan metrik yang dipilih sesuai konsekuensi false positive dan false negative.", "Software development membuat eksperimen data science menjadi artefak yang dapat digunakan ulang. Di situlah SDLC, desain modular, testing, dan deployment bertemu dengan machine learning."], "callout": "Belajar bukan menghafal istilah. Belajar berarti mampu menjelaskan keputusan model dan konsekuensinya ketika masuk ke aplikasi."}], "quiz": [{"question": "Pada 10-fold cross-validation, berapa bagian data yang dipakai untuk training di setiap fold?", "options": ["10%", "20%", "90%", "100%"], "answer": 2, "explanation": "Sembilan dari sepuluh bagian dipakai untuk training, yaitu 90%."}, {"question": "Apa arti gap training dan testing yang sangat besar?", "options": ["Model mungkin overfit", "Data pasti sudah bersih", "Model pasti underfit", "Model tidak perlu diuji lagi"], "answer": 0, "explanation": "Gap besar dapat menunjukkan model menghafal data training dan kurang mampu melakukan generalisasi."}, {"question": "Metrik apa yang membantu menilai kemampuan menangkap seluruh kasus positif?", "options": ["Recall", "Latency", "Size", "Throughput"], "answer": 0, "explanation": "Recall mengukur proporsi kasus positif aktual yang berhasil ditemukan model."}, {"question": "Apa peran utama software engineering setelah model dibuat?", "options": ["Menghapus dataset", "Membungkus model agar dapat digunakan, diuji, dan dipelihara", "Mengganti semua label", "Menaikkan akurasi secara otomatis"], "answer": 1, "explanation": "Model perlu diintegrasikan ke aplikasi dengan API, validasi, deployment, dan monitoring."}, {"question": "Mengapa akurasi dapat menyesatkan pada data imbalance?", "options": ["Akurasi tidak pernah bisa dihitung", "Kelas mayoritas dapat membuat skor tinggi walau kelas minoritas gagal dikenali", "Akurasi hanya berlaku untuk regresi", "Akurasi selalu lebih kecil dari recall"], "answer": 1, "explanation": "Model dapat selalu memilih kelas mayoritas dan tetap memperoleh akurasi tinggi."}]}, "pertemuan-03": {"courseId": "se4ds", "sessionId": "pertemuan-03", "eyebrow": "Session 03 · M-058", "title": "Agile Principles", "lead": "Agile membantu tim mengirim software lebih cepat dengan feedback yang nyata, bukan dengan menghapus perencanaan.", "sections": [{"id": "manifesto", "label": "Manifesto", "title": "Nilai yang mengubah cara tim bekerja", "body": ["Manifesto Agile menempatkan individu dan interaksi di atas proses dan tools, working software di atas dokumentasi yang berlebihan, kolaborasi customer di atas negosiasi kontrak, serta respons terhadap perubahan di atas mengikuti rencana secara kaku.", "Nilai di sebelah kanan tetap berguna. Agile hanya menekankan bahwa software yang bekerja dan feedback pengguna harus menjadi bukti utama kemajuan."], "callout": "Agile bukan berarti tanpa proses. Agile berarti proses dipakai untuk menghasilkan feedback lebih cepat."}, {"id": "praktik", "label": "Praktik tim", "title": "Scrum, Kanban, dan XP", "body": ["Scrum bekerja dalam sprint dengan backlog, planning, daily meeting, review, dan retrospective. Kanban memvisualisasikan pekerjaan dan membatasi work in progress agar bottleneck terlihat.", "Extreme Programming menekankan praktik engineering seperti pair programming, refactoring, simple design, dan automated testing. Ketiganya dapat dipilih sesuai konteks, bukan dipakai sebagai ritual kosong."], "callout": "Backlog yang baik berisi pekerjaan yang bisa dipahami, diprioritaskan, dan diuji."}], "quiz": [{"question": "Apa yang lebih diprioritaskan Agile daripada mengikuti rencana secara kaku?", "options": ["Merespons perubahan", "Menambah rapat", "Menghapus testing", "Membuat dokumentasi tanpa akhir"], "answer": 0, "explanation": "Agile mengutamakan respons terhadap perubahan."}, {"question": "Apa fungsi utama Kanban?", "options": ["Membatasi pekerjaan berjalan dan melihat alur", "Menghapus backlog", "Mengganti semua developer", "Menaikkan ukuran sprint"], "answer": 0, "explanation": "Kanban membantu melihat flow dan mengendalikan work in progress."}, {"question": "Apa tujuan retrospective?", "options": ["Memperbaiki cara kerja tim", "Menilai pengguna", "Menghapus produk", "Menambah scope tanpa diskusi"], "answer": 0, "explanation": "Retrospective digunakan untuk perbaikan proses secara berkala."}]}, "pertemuan-04": {"courseId": "se4ds", "sessionId": "pertemuan-04", "eyebrow": "Session 04 · M-058", "title": "Agile Development Techniques", "lead": "Teknik Agile membuat kebutuhan, kode, dan pengujian bergerak dalam satu alur yang bisa diperiksa.", "sections": [{"id": "story", "label": "User story", "title": "Mulai dari kebutuhan yang bisa diuji", "body": ["User story menjelaskan siapa yang membutuhkan fitur, apa yang ingin dilakukan, dan manfaatnya. Epic adalah kebutuhan besar yang dipecah menjadi beberapa story; task adalah pekerjaan teknis untuk menyelesaikannya.", "Acceptance criteria mengubah kalimat umum menjadi kondisi yang dapat diperiksa. Ini mengurangi perbedaan tafsir antara pengguna, developer, dan tester."], "callout": "Story belum selesai jika belum ada cara yang jelas untuk membuktikan bahwa story itu selesai."}, {"id": "delivery", "label": "Delivery", "title": "Testing berjalan bersama pengembangan", "body": ["Test-Driven Development dimulai dari test yang gagal, implementasi minimum, lalu refactoring. Continuous Integration menjalankan build dan test setiap ada perubahan agar masalah ditemukan lebih awal.", "Continuous Delivery menjaga software selalu siap dirilis. Pada data science, pipeline test juga dapat memeriksa schema, missing value, dan kualitas fitur."], "callout": "Feedback pendek membuat biaya memperbaiki kesalahan tetap kecil."}], "quiz": [{"question": "Apa fungsi acceptance criteria?", "options": ["Menentukan kondisi selesai yang dapat diuji", "Mengganti user story", "Menghapus test", "Menentukan gaji tim"], "answer": 0, "explanation": "Acceptance criteria membuat hasil yang diharapkan dapat diverifikasi."}, {"question": "TDD dimulai dengan apa?", "options": ["Test yang gagal", "Deploy production", "Dokumentasi akhir", "Dashboard bisnis"], "answer": 0, "explanation": "Siklus TDD dimulai dari red test."}, {"question": "Apa tujuan Continuous Integration?", "options": ["Menemukan masalah perubahan lebih awal", "Menghindari version control", "Membuat sprint lebih panjang", "Menghapus review"], "answer": 0, "explanation": "CI menggabungkan perubahan dan menjalankan pemeriksaan secara rutin."}]}, "pertemuan-05": {"courseId": "se4ds", "sessionId": "pertemuan-05", "eyebrow": "Session 05 · M-058", "title": "DevOps Principles", "lead": "DevOps menyatukan development dan operations agar software dapat dikirim, dijalankan, dan dipelihara sebagai tanggung jawab bersama.", "sections": [{"id": "culture", "label": "Budaya", "title": "Dari handoff menuju kolaborasi", "body": ["DevOps bukan sekadar tools. Ia adalah budaya kolaborasi, feedback, automation, dan shared ownership antara tim yang membangun software dan tim yang menjalankannya.", "Dengan tanggung jawab bersama, masalah production menjadi input perbaikan, bukan alasan untuk saling menyalahkan."], "callout": "Software yang belum bisa dioperasikan belum benar-benar selesai."}, {"id": "cicd", "label": "CI/CD", "title": "Delivery yang berulang dan aman", "body": ["Continuous Integration memvalidasi perubahan secara otomatis. Continuous Delivery menyiapkan artefak agar dapat dirilis, sedangkan Continuous Deployment dapat merilis perubahan secara otomatis setelah gate terpenuhi.", "Automation mengurangi pekerjaan manual yang rentan salah. Monitoring memberi sinyal apakah perubahan benar-benar memperbaiki layanan."], "callout": "Pipeline delivery adalah executable documentation dari cara software dirilis."}], "quiz": [{"question": "DevOps menggabungkan disiplin apa?", "options": ["Development dan Operations", "Design dan Sales", "Data dan Finance", "Testing dan Marketing"], "answer": 0, "explanation": "DevOps menghubungkan development dan operations."}, {"question": "Apa manfaat automation dalam delivery?", "options": ["Mengurangi langkah manual yang berulang", "Menghapus monitoring", "Menyembunyikan error", "Menghindari testing"], "answer": 0, "explanation": "Automation membuat proses konsisten dan dapat diulang."}, {"question": "Apa yang dimaksud shared ownership?", "options": ["Tim bersama-sama bertanggung jawab atas layanan", "Satu orang mengerjakan semuanya", "Tidak ada yang bertanggung jawab", "Pengguna menulis seluruh kode"], "answer": 0, "explanation": "Tim berbagi tanggung jawab dari build hingga operasi."}]}, "pertemuan-06": {"courseId": "se4ds", "sessionId": "pertemuan-06", "eyebrow": "Session 06 · M-058", "title": "DevOps Tools and Practices", "lead": "Tools membantu DevOps, tetapi praktik version control, observability, dan keamanan tetap menjadi fondasinya.", "sections": [{"id": "tools", "label": "Toolchain", "title": "Satu alur dari commit ke deployment", "body": ["Version control menyimpan riwayat perubahan dan memungkinkan kolaborasi. Jenkins dapat mengorkestrasi build dan test; Docker mengemas aplikasi secara konsisten; Kubernetes membantu mengelola container dalam skala lebih besar.", "Pemilihan tools sebaiknya mengikuti masalah yang ingin diselesaikan. Tool yang banyak tidak otomatis membuat delivery lebih baik."], "callout": "Pahami alurnya dulu, baru pilih tools."}, {"id": "observe", "label": "Observability", "title": "Lihat apa yang terjadi setelah rilis", "body": ["Logging menyimpan kejadian penting, metrics mengukur kondisi sistem, dan tracing mengikuti perjalanan satu request. Ketiganya membantu diagnosis performa dan kegagalan.", "Safety dan security masuk ke pipeline: secret tidak ditaruh di repository, image dipindai, dan akses dibatasi sesuai kebutuhan."], "callout": "Sistem yang tidak terlihat sulit dirawat."}], "quiz": [{"question": "Apa fungsi version control?", "options": ["Menyimpan riwayat dan kolaborasi perubahan", "Menghapus semua versi lama", "Menjalankan database production", "Menggantikan testing"], "answer": 0, "explanation": "Version control menjaga riwayat perubahan dan kolaborasi."}, {"question": "Docker terutama membantu dalam hal apa?", "options": ["Mengemas aplikasi dan dependensinya", "Menulis user story", "Mengukur precision", "Menggambar dashboard"], "answer": 0, "explanation": "Container membuat lingkungan aplikasi lebih konsisten."}, {"question": "Apa contoh observability?", "options": ["Logs, metrics, dan traces", "Logo, warna, dan font", "Backlog, sprint, dan epic", "Label, target, dan feature"], "answer": 0, "explanation": "Observability memakai telemetry untuk memahami sistem."}]}, "pertemuan-07": {"courseId": "se4ds", "sessionId": "pertemuan-07", "eyebrow": "Session 07 · M-058", "title": "Introduction to Machine Learning", "lead": "Machine learning mencari pola dari data, lalu memakai pola itu untuk membuat prediksi pada data baru.", "sections": [{"id": "types", "label": "Jenis ML", "title": "Supervised, unsupervised, dan reinforcement", "body": ["Supervised learning memiliki label dan mencakup regresi serta klasifikasi. Unsupervised learning mencari struktur tanpa label, misalnya clustering. Reinforcement learning belajar dari aksi, lingkungan, dan reward.", "Memilih jenis pembelajaran harus dimulai dari bentuk masalah dan ketersediaan label, bukan dari algoritma yang sedang populer."], "callout": "Tentukan pertanyaan dan target sebelum menentukan model."}, {"id": "tradeoff", "label": "Model", "title": "Bias, variance, dan generalisasi", "body": ["Preprocessing menyiapkan data, training mempelajari pola, dan evaluation mengukur performa. Model dengan bias tinggi cenderung underfit; model dengan variance tinggi cenderung overfit.", "Sweet spot berada di antara keduanya: cukup kompleks untuk menangkap hubungan, tetapi tidak ikut menghafal noise."], "callout": "Validation membantu memilih model yang bekerja pada data yang belum pernah dilihat."}], "quiz": [{"question": "Regresi biasanya memprediksi apa?", "options": ["Nilai kontinu", "Kategori warna saja", "Urutan commit", "Jumlah developer"], "answer": 0, "explanation": "Regresi digunakan untuk nilai numerik kontinu."}, {"question": "Apa ciri overfitting?", "options": ["Sangat baik di training tetapi buruk pada data baru", "Buruk di semua data", "Tidak memiliki fitur", "Tidak bisa dilatih"], "answer": 0, "explanation": "Overfit menghafal training dan gagal generalisasi."}, {"question": "Apa fungsi preprocessing?", "options": ["Menyiapkan data sebelum training", "Menghapus model", "Mengganti pengguna", "Merilis aplikasi otomatis"], "answer": 0, "explanation": "Preprocessing membersihkan dan mengubah data agar siap dipakai model."}]}, "pertemuan-09": {"courseId": "se4ds", "sessionId": "pertemuan-09", "eyebrow": "Session 09 · M-058", "title": "Integrating ML in Software Development", "lead": "ML menjadi fitur produk ketika data pipeline, feature engineering, dan model diperlakukan sebagai bagian dari sistem.", "sections": [{"id": "pipeline", "label": "Pipeline", "title": "Data harus sampai ke model dengan konsisten", "body": ["Pipeline mengambil data, membersihkan, mengubah fitur, lalu mengirimkannya ke model. Langkah training dan inference perlu memakai transformasi yang konsisten agar tidak terjadi training-serving skew.", "Feature engineering mengubah data mentah menjadi sinyal yang berguna. Setiap feature perlu memiliki definisi, sumber, tipe, dan aturan validasi."], "callout": "Model bagus dengan pipeline yang rapuh tetap menghasilkan software yang rapuh."}, {"id": "production", "label": "Production", "title": "Model hidup di dalam lingkungan nyata", "body": ["Di production, model berhadapan dengan latency, error input, perubahan distribusi data, dan kebutuhan rollback. Karena itu model perlu versioning, contract input, logging, dan monitoring.", "Deployment dapat berbentuk batch prediction atau layanan real-time. Pilihan bergantung pada kebutuhan waktu dan biaya."], "callout": "Deploy bukan akhir. Deploy adalah awal dari observasi."}], "quiz": [{"question": "Apa risiko training-serving skew?", "options": ["Transformasi training dan inference berbeda", "Model terlalu kecil", "UI terlalu hijau", "Backlog terlalu panjang"], "answer": 0, "explanation": "Skew muncul saat fitur diproses berbeda antara training dan serving."}, {"question": "Mengapa model perlu versioning?", "options": ["Agar artefak dapat dilacak dan di-rollback", "Agar file lebih besar", "Agar label hilang", "Agar testing dilewati"], "answer": 0, "explanation": "Versioning membuat perubahan model dapat ditelusuri."}, {"question": "Batch prediction cocok untuk apa?", "options": ["Prediksi berkala dalam jumlah besar", "Jawaban setiap request detik itu juga", "Menghapus data", "Menyusun sprint"], "answer": 0, "explanation": "Batch memproses data secara berkala, bukan per request."}]}, "pertemuan-10": {"courseId": "se4ds", "sessionId": "pertemuan-10", "eyebrow": "Session 10 · M-058", "title": "Introduction to Data Science", "lead": "Data adalah bahan baku keputusan. Kualitasnya menentukan seberapa jauh analisis dapat dipercaya.", "sections": [{"id": "water", "label": "Data sebagai aset", "title": "Data mengalir seperti air", "body": ["Materi menggambarkan data seperti air: tersedia di banyak tempat, mengalir antar sistem, tetapi dapat kotor, stale, dan sulit digunakan jika tidak dikelola.", "Perusahaan perlu membersihkan data sejak sumbernya, memahami tujuan penggunaan, dan mengelola data sebagai proyek jangka panjang."], "callout": "Banyak data tidak sama dengan banyak informasi yang berguna."}, {"id": "process", "label": "Proses analisis", "title": "Dari pertanyaan menuju keputusan", "body": ["Data science dimulai dari pertanyaan, pengumpulan data, pembersihan, eksplorasi, analisis atau model, lalu komunikasi hasil. Setiap tahap harus kembali memeriksa apakah hasil menjawab kebutuhan awal.", "Data quality bersifat fit for purpose: standar kualitas bergantung pada keputusan yang akan dibuat."], "callout": "Mulai dari keputusan yang ingin dibantu, bukan dari dataset yang kebetulan tersedia."}], "quiz": [{"question": "Mengapa data perlu dikelola sejak sumbernya?", "options": ["Agar kualitas tidak rusak sejak awal", "Agar data lebih sulit dipakai", "Agar semua data menjadi besar", "Agar analisis dilewati"], "answer": 0, "explanation": "Kualitas lebih murah dijaga dari sumber daripada diperbaiki di akhir."}, {"question": "Apa arti fit for purpose?", "options": ["Kualitas sesuai tujuan penggunaannya", "Semua data harus sempurna", "Data harus selalu real-time", "Data hanya boleh berupa tabel"], "answer": 0, "explanation": "Kebutuhan kualitas bergantung pada konteks keputusan."}, {"question": "Apa langkah awal data science?", "options": ["Merumuskan pertanyaan", "Deploy model", "Menghapus data", "Membuat chart acak"], "answer": 0, "explanation": "Pertanyaan menentukan data dan analisis yang relevan."}]}, "pertemuan-11": {"courseId": "se4ds", "sessionId": "pertemuan-11", "eyebrow": "Session 11 · M-058", "title": "Data Science Tools and Techniques", "lead": "Tools mempercepat eksplorasi, tetapi pemahaman proses tetap lebih penting daripada nama aplikasinya.", "sections": [{"id": "tools", "label": "Tools", "title": "Notebook untuk berpikir, kode untuk mengulang", "body": ["Python, R, dan Jupyter Notebook sering digunakan untuk eksplorasi, analisis, dan komunikasi eksperimen. Notebook membantu melihat data secara interaktif, sementara script dan package membantu membuat proses dapat diulang.", "Pemisahan eksplorasi dan pipeline produksi mencegah eksperimen ad hoc langsung menjadi sistem yang sulit dirawat."], "callout": "Notebook bagus untuk menemukan jawaban; pipeline bagus untuk mengulang jawaban."}, {"id": "visual", "label": "Visualisasi", "title": "Grafik harus menjawab pertanyaan", "body": ["Visualisasi membantu menemukan pola, outlier, tren, dan perbandingan. Pilih bentuk grafik berdasarkan pesan: garis untuk waktu, batang untuk perbandingan, dan sebar untuk hubungan.", "Dalam software development, visualisasi juga membantu stakeholder memahami performa sistem dan kualitas data."], "callout": "Jika grafik tidak membantu keputusan, ia hanya menjadi dekorasi."}], "quiz": [{"question": "Apa keunggulan notebook?", "options": ["Eksplorasi interaktif", "Menggantikan semua deployment", "Menjamin data bersih", "Menghapus dokumentasi"], "answer": 0, "explanation": "Notebook cocok untuk eksplorasi dan komunikasi langkah analisis."}, {"question": "Grafik garis cocok untuk apa?", "options": ["Melihat perubahan dari waktu ke waktu", "Membandingkan password", "Menyimpan model", "Menghapus outlier otomatis"], "answer": 0, "explanation": "Garis menonjolkan tren temporal."}, {"question": "Mengapa script produksi dibutuhkan?", "options": ["Agar proses dapat diulang dan diuji", "Agar notebook hilang", "Agar visualisasi dilarang", "Agar data tidak terdokumentasi"], "answer": 0, "explanation": "Script membantu reproduksibilitas dan automation."}]}, "pertemuan-12": {"courseId": "se4ds", "sessionId": "pertemuan-12", "eyebrow": "Session 12 · M-058", "title": "MLOps", "lead": "MLOps menghubungkan machine learning dan DevOps untuk mengembangkan, menguji, merilis, dan memelihara model.", "sections": [{"id": "cycle", "label": "Siklus MLOps", "title": "Model memiliki siklus hidup", "body": ["MLOps mengotomatisasi praktik development, testing, deployment, dan maintenance model di lingkungan operasional. Siklusnya mencakup data, training, registry, serving, monitoring, dan retraining.", "Berbeda dari software biasa, performa model dapat turun walau kode tidak berubah karena data dan dunia berubah."], "callout": "Yang dimonitor bukan hanya service hidup, tetapi juga apakah prediksi masih berguna."}, {"id": "monitor", "label": "Monitoring", "title": "Dengarkan sinyal setelah rilis", "body": ["Monitoring dapat memeriksa latency, error rate, data drift, concept drift, dan kualitas prediksi ketika label sudah tersedia. Evaluasi berkala membantu menentukan kapan model perlu dilatih ulang.", "Optimasi harus berbasis bukti: perbaiki bottleneck yang terlihat, bukan menambah kompleksitas tanpa ukuran."], "callout": "Model production tanpa monitoring adalah eksperimen yang dilepas tanpa alarm."}], "quiz": [{"question": "MLOps merupakan gabungan ML dan apa?", "options": ["DevOps", "Design", "Sales", "Accounting"], "answer": 0, "explanation": "MLOps membawa praktik DevOps ke siklus hidup ML."}, {"question": "Apa itu data drift?", "options": ["Distribusi input berubah", "Kode selalu sama", "Model disimpan", "UI berganti warna"], "answer": 0, "explanation": "Data drift adalah perubahan pola atau distribusi data input."}, {"question": "Mengapa retraining dibutuhkan?", "options": ["Performa model dapat turun saat dunia berubah", "Agar model selalu lebih besar", "Agar testing dihapus", "Agar data lama hilang"], "answer": 0, "explanation": "Retraining dapat memulihkan relevansi model terhadap data baru."}]}, "pertemuan-13": {"courseId": "se4ds", "sessionId": "pertemuan-13", "eyebrow": "Session 13 · M-058", "title": "Data Security and Regulation in MLOps", "lead": "Pipeline ML harus aman dari serangan, kebocoran data, dan penggunaan yang melanggar aturan.", "sections": [{"id": "secure", "label": "Keamanan", "title": "Lindungi seluruh rantai data", "body": ["Secure ML pipeline melindungi sumber data, storage, feature pipeline, registry, endpoint, dan log. Terapkan least privilege, secret management, encryption, dependency scanning, dan audit trail.", "Model juga dapat menjadi target serangan melalui data poisoning, prompt atau input abuse, dan pencurian artefak. Threat modeling membantu tim memikirkan risiko sebelum rilis."], "callout": "Keamanan bukan tahap terakhir; ia adalah constraint desain sejak awal."}, {"id": "privacy", "label": "Privasi", "title": "Data pribadi memiliki batas penggunaan", "body": ["Gunakan hanya data yang diperlukan, pahami tujuan pemrosesan, batasi akses, dan simpan data sesuai kebijakan. Pseudonymization dan retention policy dapat mengurangi risiko.", "Regulasi berbeda menurut konteks dan wilayah. Dokumentasikan sumber data, dasar penggunaan, pemilik, serta keputusan yang diambil oleh sistem."], "callout": "Model yang akurat tetap tidak dapat dibenarkan jika datanya digunakan tanpa dasar."}], "quiz": [{"question": "Apa prinsip least privilege?", "options": ["Akses hanya sesuai kebutuhan", "Semua orang menjadi admin", "Akses tidak pernah dicatat", "Password dibagikan"], "answer": 0, "explanation": "Least privilege membatasi akses sesuai kebutuhan tugas."}, {"question": "Apa contoh perlindungan pipeline?", "options": ["Secret management dan audit log", "Menaruh key di repository", "Menghapus monitoring", "Membuka semua endpoint"], "answer": 0, "explanation": "Secret management dan audit membantu mengurangi risiko."}, {"question": "Mengapa retention policy penting?", "options": ["Mengatur berapa lama data disimpan", "Membuat data selalu publik", "Menghapus consent", "Menaikkan akurasi otomatis"], "answer": 0, "explanation": "Retention policy membatasi penyimpanan data yang tidak lagi diperlukan."}]}, "pertemuan-14": {"courseId": "se4ds", "sessionId": "pertemuan-14", "eyebrow": "Session 14 · M-058", "title": "Integrative Project", "lead": "Proyek integratif membawa konsep data, software, dan kerja tim ke masalah nyata.", "sections": [{"id": "team", "label": "Tim", "title": "Gabungkan perspektif yang berbeda", "body": ["Tim multidisiplin menggabungkan kemampuan domain, data, software, desain, dan komunikasi. Perbedaan perspektif membantu menemukan risiko yang mungkin terlewat jika semua orang memiliki sudut pandang sama.", "Peran harus jelas, tetapi pengetahuan penting tetap dibagikan melalui review, dokumentasi, dan demo."], "callout": "Kolaborasi yang baik bukan membagi silo; kolaborasi membuat keputusan terlihat."}, {"id": "project", "label": "Eksekusi", "title": "Dari problem statement menuju bukti", "body": ["Mulai dengan problem statement dan kriteria sukses. Bangun irisan kecil yang dapat didemokan, ukur hasilnya, lalu gunakan feedback untuk memperbaiki solusi.", "Laporan proyek sebaiknya menunjukkan konteks, data, keputusan desain, hasil evaluasi, batasan, dan pekerjaan lanjutan."], "callout": "Proyek selesai bukan ketika semua ide masuk, tetapi ketika solusi dapat dijelaskan dan dievaluasi."}], "quiz": [{"question": "Mengapa tim multidisiplin berguna?", "options": ["Menyatukan perspektif dan keahlian", "Menghapus komunikasi", "Membuat semua orang melakukan hal sama", "Menghindari evaluasi"], "answer": 0, "explanation": "Perspektif berbeda membantu problem solving dan inovasi."}, {"question": "Apa langkah awal proyek integratif?", "options": ["Problem statement dan kriteria sukses", "Membeli semua tools", "Membuat logo", "Deploy tanpa data"], "answer": 0, "explanation": "Masalah dan ukuran sukses memberi arah proyek."}, {"question": "Apa yang sebaiknya ada dalam laporan?", "options": ["Keputusan, hasil, batasan, dan evaluasi", "Hanya screenshot", "Hanya kode", "Hanya judul"], "answer": 0, "explanation": "Laporan harus membuat proses dan hasil dapat dipahami."}]}, "pertemuan-15": {"courseId": "se4ds", "sessionId": "pertemuan-15", "eyebrow": "Session 15 · M-058", "title": "Project Evaluation and Reflection", "lead": "Evaluasi menilai bukan hanya hasil akhir, tetapi juga cara solusi dibangun dan apa yang dipelajari.", "sections": [{"id": "evaluate", "label": "Evaluasi", "title": "Bandingkan tujuan dengan bukti", "body": ["Evaluasi memeriksa apakah tujuan proyek tercapai, apakah pendekatan yang dipilih efektif, dan apakah hasil selaras dengan kebutuhan awal. Lihat kualitas teknis, kualitas data, usability, biaya, dan risiko.", "Gunakan bukti yang sesuai: metrik model, hasil test, feedback pengguna, latency, reliability, atau indikator bisnis."], "callout": "Angka harus dibaca bersama konteks dan batasannya."}, {"id": "reflect", "label": "Refleksi", "title": "Jadikan pengalaman sebagai pengetahuan", "body": ["Refleksi individual meninjau keputusan yang berhasil, kesalahan yang terjadi, asumsi yang terbukti salah, dan kebiasaan yang ingin diubah. Refleksi bukan menyalahkan diri, melainkan membuat pembelajaran dapat dipakai pada proyek berikutnya.", "Data-driven software development terus berulang: pertanyaan, data, software, feedback, dan perbaikan."], "callout": "Dokumentasikan bukan hanya apa yang dibuat, tetapi mengapa keputusan itu diambil."}], "quiz": [{"question": "Apa yang dibandingkan dalam evaluasi proyek?", "options": ["Tujuan awal dan bukti hasil", "Warna UI saja", "Jumlah rapat saja", "Nama repository"], "answer": 0, "explanation": "Evaluasi memeriksa ketercapaian tujuan melalui bukti."}, {"question": "Apa tujuan refleksi?", "options": ["Mengubah pengalaman menjadi pembelajaran", "Mencari pihak untuk disalahkan", "Menghapus hasil", "Menghindari feedback"], "answer": 0, "explanation": "Refleksi membantu pembelajaran untuk pekerjaan berikutnya."}, {"question": "Mengapa batasan perlu dilaporkan?", "options": ["Agar hasil dibaca secara jujur dan tepat konteks", "Agar proyek terlihat gagal", "Agar testing dihapus", "Agar model selalu dipercaya"], "answer": 0, "explanation": "Batasan mencegah kesimpulan yang terlalu luas."}]}}};
